          "content": "Google Research가 마운틴뷰에서 열린 Research@ 행사에서 최근 성과를 공유했어요. 블로그 글은 여러 항목을 짧게 소개하고, 각 항목의 자세한 내용은 별도 페이지로 연결해요.\n\n글에 담긴 항목은 다음과 같아요.\n\n- Deep Review: 공개 출시를 알렸어요. Google은 STOC, ICML, NeurIPS, ICLR의 제출 논문 1만 5천 건 이상에 쓴 뒤 공개한다고 밝혔어요.\n- Google Earth AI: 공중보건 도구를 소개했어요.\n- PDFM: 모델이 함께 언급됐어요.\n- AMIE: 1차 진료 클리닉에서 AMIE를 다룬 동료 심사 연구가 The Lancet에 실렸다고 소개했어요.\n\n각 항목의 세부 내용은 연결된 페이지에 있어서, 이 글만으로는 성능이나 효과를 판단하기 어려워요.",
