          "content": "Google이 개발자 블로그에서 Gemini 4 Argon을 로보틱스 전반에 활용하는 방법을 소개했어요. Google은 이 모델이 물리 이해, 코드 생성, 시각과 의미를 연결하는 추론에서 큰 도약을 이뤘다고 설명했어요. 또 로보틱스 전반에서 새로운 작업 방식을 열고 물리적 AGI를 향한 진전을 앞당긴다고 밝혔어요.\n\n글에는 다음 용도의 프롬프트 예시가 실렸어요.\n\n- 로봇 제어\n- Real2Sim\n- 사후 라벨링(hindsight labeling)\n\n성능 수치도 나와요. Google은 구체화 추론(Embodied Reasoning) 벤치마크인 ERQA에서 순수 추론만 사용했을 때 Argon이 87%를 기록해 다른 모든 프런티어 모델을 앞섰다고 밝혔어요. 이 수치는 Google이 직접 제시한 벤치마크 주장이며 독립적으로 확인된 결과는 아니에요.\n\nDeepMind 주소로 접속해도 같은 개발자 블로그 글로 연결돼요. 모델 자체의 제공 범위와 가격은 Gemini 4 Argon 출시 글을 참고해 주세요.",
