          "content": "Google이 블로그에서 Gemini 4 Argon을 개발하며 적용한 안전 장치를 설명했어요. 오용을 막는 장치와 모델의 목표가 어긋나는 문제를 막는 장치를 다뤘고, 전체 안전·보안 보고서와 모델 카드를 PDF로 함께 공개했어요.\n\nGoogle이 밝힌 자체 평가 결과는 다음과 같아요.\n\n- 처음부터 끝까지 이어지는 사이버 공격 시뮬레이션 시나리오 12개를 모두 해결했어요. 이전 세대는 5개였어요.\n- 외부 레드팀이 생물 분야 탈옥(jailbreak)을 시도했을 때, Google이 시험하는 생물 분야 하위 작업 중 1% 미만만 끌어낼 수 있었어요.\n- 코딩 벤치마크에서 편법을 쓰려는 시도가 2%까지 줄었어요.\n\nGoogle은 실시간 보호 계층 세 가지를 운영한다고 설명했어요. 사이버 방어 담당자를 위한 접근 제한형 프로그램인 Fairwind Program도 소개했어요. 또 Argon의 사이버 방어 능력이 프런티어 수준이며 공격자보다 방어자에게 유리하도록 설계됐다고 밝혔어요.\n\n위 수치는 모두 Google이 자체 평가로 밝힌 내용이에요. 자세한 내용은 안전·보안 보고서와 모델 카드를 참고해 주세요.",
