          "content": "Gemini CLI v0.64.0이 안정 릴리스로 나왔어요. 릴리스 본문은 자동으로 만든 변경 이력이며 대표 기능 설명은 없어요.\n\n변경 이력에 오른 항목 가운데 두 가지는 다음과 같아요.\n\n- a2a-server: 설정을 V1에서 V2로 옮기는 마이그레이션 로직을 구현했어요.\n- ACP: PromptResponse.usage 값을 연결하고 usage_update 알림을 내보내도록 고쳤어요.\n\n이 밖에도 여러 수정이 함께 들어 있어요. 전체 목록은 릴리스 페이지에서 확인할 수 있어요.",
