          "summary": "Google Play에서 Google AI Studio로 만든 맞춤 Android 앱을 내 기기에서 실행할 수 있게 됐어요. 일반 Google 계정만 있으면 되고, 앱은 공개 스토어 카탈로그와 분리돼요. 미국 등 일부 국가의 만 18세 이상 사용자부터 순차 제공돼요.",
          "content": "Google이 Google Play에서 Google AI Studio로 만든 개인용 Android 앱을 쓸 수 있게 한다고 밝혔어요. Google AI Studio에서 바이브 코딩으로 맞춤 Android 앱을 만든 뒤, Google Play를 통해 내 기기에서 실행하는 방식이에요.\n\n필요한 것은 일반 Google 계정이고, 개발자 계정은 필요 없다고 Google이 설명했어요. 이렇게 만든 앱은 비공개로 유지되며 공개 스토어 카탈로그와 분리된다고 해요.\n\n제공 범위에는 제한이 있어요. Google은 이 기능이 미국을 포함한 일부 국가에서 만 18세 이상 사용자를 대상으로 안내 당일부터 순차 제공된다고 밝혔어요. 미국 외에 어떤 국가가 포함되는지는 글에 나와 있지 않아요.\n\n같은 글에서 Google은 AI 기반 탐색 기능인 Ask Play 비교, Game Finder, Play in Gemini도 함께 소개했어요.",
