          "content": "Ai2가 10월 14일 Hugging Face 블로그에 HiRO-ACEv2를 소개했어요. Ai2는 이 모델을 High Resolution Output Ai2 Climate Emulator(HiRO-ACE) 시스템의 최신 업데이트라고 밝혔고, 100km 해상도의 거친 출력을 3km 해상도의 극한 기상 데이터로 바꿔 주는 기후 에뮬레이터라고 설명해요.\n\n수치는 모두 Ai2가 직접 밝힌 값이에요. Ai2는 전체 시스템이 전 지구 3km 기후 데이터를 물리 모델 X-SHiELD 대비 약 1/300 비용으로 만들 수 있다고 했어요. 거칠게 만든 X-SHiELD 데이터를 입력하면 목표 시뮬레이션의 고해상도 통계와 3% 이내로 일치한다고도 했어요.\n\n한계도 함께 적혀 있어요. HiRO는 X-SHiELD에 맞춰 조정된 ACE 버전에서만 작동하고, 다른 기후에는 아직 쓸 수 없어요. 글에는 Hugging Face의 allenai/HiRO-ACEv2 모델 저장소로 연결되는 링크가 달려 있어요.",
