            "summary": "Ai2 released HiRO-ACEv2, an AI climate emulator that turns coarse 100 km output into 3 km extreme-weather data. Ai2 says it costs about 1/300th of running the X-SHiELD physics model, and says it cannot yet cover other climates.",
            "content": "Ai2 introduced HiRO-ACEv2 on the Hugging Face blog on October 14. Ai2 calls it the newest update to its High Resolution Output Ai2 Climate Emulator (HiRO-ACE) system, a climate emulator that turns coarse 100 km output into extreme-weather data at 3 km resolution.\n\nAll figures are Ai2's own. Ai2 said the full system can generate global 3 km climate data at about 1/300th the cost of the X-SHiELD physics model. It also said that, given coarsened X-SHiELD data, the model matches the target simulation's high-resolution statistics to within 3%.\n\nThe post also states a limit. HiRO only works with the version of ACE tuned to X-SHiELD, and it cannot yet cover other climates. The post links to the allenai/HiRO-ACEv2 model repository on Hugging Face."
