          "content": "AI21 Labs가 10월 15일 블로그에서, 자사 Forward-Deployed Researchers가 최근 공개된 NVIDIA Nemotron 3.5 Super VL을 Gong, Deel, Alice와 협력해 후속 학습(post-training)했다고 밝혔어요. AI21은 이렇게 만든 특화 모델이 정해진 용도에서 프런티어 모델의 품질을 넘거나 맞추면서 비용은 훨씬 낮다고 주장해요. 작업은 3주에 걸쳐 진행됐다고 해요.\n\n보고된 결과는 파트너별로 아래와 같아요. 모두 AI21과 파트너가 직접 밝힌 값이에요.\n\n- Gong: 자체 평가에서 속도와 정확도 모두 Claude Opus 5.5 같은 최상위 모델에 맞먹는다고 밝혔어요.\n- Deel: Emet의 8개국 급여 벤치마크 평가에서 답변 정확도가 72%로 올랐고, Claude Opus 5.5보다 8포인트 높으면서 질의당 비용은 33배 낮다고 했어요.\n- Alice: 공격 저항성이 41포인트 개선됐다고 했어요.\n\nAlice 수치는 표기가 달라요. AI21은 41포인트라고 쓰고, NVIDIA 기술 블로그는 정확도가 41% 올랐다고 적어서 개선 폭을 하나로 확정하기 어려워요. NVIDIA 발표 글도 AI21과 Alice가 사이버 보안 공격 저항성을 위해 후속 학습했다고 적고 있어요. 글에는 공개 일정이나 가격이 나와 있지 않아요.",
