            "content": "In a blog post on October 15, AI21 Labs said its Forward-Deployed Researchers post-trained the recently released NVIDIA Nemotron 3.5 Super VL in partnership with Gong, Deel and Alice. AI21 claims the specialized models surpass or match frontier quality on their defined use cases at a fraction of the cost. The work reportedly took three weeks.\n\nThe reported results are listed by partner below. All of them are figures that AI21 and its partners reported themselves.\n\n- Gong: In its own evaluations, Gong said the model matches top models such as Claude Opus 5.5 in speed and accuracy.\n- Deel: On Emet's 8-country payroll benchmark evaluation, answer accuracy rose to 72%, which Deel put 8 points above Claude Opus 5.5 at 33x less cost per query.\n- Alice: Attack resilience improved by 41 points, according to the post.\n\nThe Alice figure is worded differently across sources. AI21 writes 41 points, while the NVIDIA tech blog says accuracy improved 41%, so the size of the gain is hard to pin down. NVIDIA's release post also says AI21 and Alice post-trained the model for cybersecurity attack resilience. The post gives no release date or price."
