          "content": "Anthropic이 10월 18일 회사 지분 일부를 Anthropic Public Benefit Fund에 배정한다고 발표했어요. 이 기금은 새로 만든 법인이고, 회사가 성장할수록 기금의 지분이 늘어나는 구조라고 Anthropic은 설명해요.\n\nAnthropic이 밝힌 세부 조건은 다음과 같아요.\n\n- 주주 승인을 전제로 Anthropic 지분의 5%를 먼저 배정해요.\n- 회사 가치가 정해진 기준선보다 50% 오를 때마다 이사회 재량으로 2%를 추가할 수 있어요.\n- 기금은 wholly-owned 유한책임회사(LLC)라고 밝혔어요.\n- 기금이 가진 지분은 로비나 정치 후원에 쓰이지 않는다고 밝혔어요.\n\n지분 비율이 시간이 지나며 늘어날 수 있는 구조이므로, 5%는 출발점에 해당해요. 다만 이 배정은 주주 승인을 전제로 하기 때문에 아직 확정된 것으로 읽으면 안 돼요.",
