            "deck": "The committed stake grows as the company's value rises",
            "summary": "Anthropic says it will commit part of its shares to a new entity, the Anthropic Public Benefit Fund. Subject to stockholder approval, 5% of shares are committed first, with 2% more added at the board's discretion for every 50% rise in company value above a baseline.",
            "content": "On October 18, Anthropic announced that it will commit a portion of its shares to the Anthropic Public Benefit Fund. Anthropic describes the fund as a new entity with a structure that increases the stake as the company grows.\n\nAnthropic gave the following terms.\n\n- Subject to stockholder approval, 5% of Anthropic's shares are committed first.\n- An additional 2% can be added at the board's discretion for every 50% increase in the company's value above a set baseline.\n- The fund is a wholly-owned LLC.\n- None of the fund's equity will be used for lobbying or political giving.\n\nBecause the stake can grow over time, the 5% is a starting point. The commitment is subject to stockholder approval, so it should not be read as final."
