          "deck": "2030년까지 AI가 얼마나 해낼지, 두 집단의 예상이 크게 갈렸어요",
          "summary": "Anthropic이 AI가 일과 경제에 미칠 영향을 미국 성인과 자사 직원이 어떻게 예상하는지 비교한 설문 결과를 냈어요. Anthropic은 2030년까지 AI가 노벨상 수준의 발견을 할 수 있다고 예상하는 비율이 미국 성인 39%, 직원 91%라고 밝혔어요.",
          "content": "Anthropic이 AI의 발전 속도와 일, 경제에 미칠 영향을 미국 성인과 Anthropic 직원이 어떻게 예상하는지 비교한 설문 보고서를 냈어요. 설문은 Anthropic이 2026년 8월에 직접 진행했고, 대상은 미국 성인 대표 표본과 Anthropic 직원이에요.\n\n보고서는 미국 성인도 앞으로 몇 년 안에 AI 능력이 빠르게 발전한다고 예상하지만, Anthropic 직원은 더 빠른 발전을 예상한다고 정리해요. 2030년까지 AI가 노벨상 수준의 발견을 할 수 있다고 예상하는 비율은 미국 성인 39%, 직원 91%라고 Anthropic은 밝혔어요.\n\n일에 대한 전망도 갈렸어요. 직원들은 2030년까지 AI가 자신의 현재 업무의 75%를 할 수 있을 것으로 예상했고, 미국 근로자 전체는 28%로 예상했어요.\n\n이 보고서는 어떤 일이 실제로 가능해지는지가 아니라 사람들이 무엇을 예상하는지를 묻는 설문이에요. 같은 날 나온 Anthropic의 고용 변화 보고서와 함께 개요 페이지로 묶여 있어요.",
