            "content": "Anthropic has published a survey report comparing how US adults and Anthropic staff expect AI to advance and to affect work and the economy. Anthropic ran the survey itself in August 2026, covering a nationally representative sample of US adults and Anthropic staff.\n\nThe report says US adults expect AI capabilities to advance rapidly in the coming years, and that Anthropic staff expect even faster progress. Anthropic reports that 39% of US adults and 91% of staff expect AI to be able to make a Nobel-level discovery by 2030.\n\nExpectations about work differed too. Staff members expect AI to be able to do 75% of their current work by 2030, compared to 28% for US workers overall.\n\nThe survey asks what people expect, not what AI can actually do. The report is grouped on an overview page with Anthropic's employment report published the same day."
