          "deck": "회사 안의 인력 구성과 에이전트 작업 시간을 정리한 보고서예요",
          "summary": "Anthropic의 연구 보고서에 따르면 주니어 기술 인력의 채용 비중은 27%에서 9%로, 기술 부서의 주니어 비중은 2025년 초 이후 21%에서 14%로 줄었어요. 보고서는 8월까지 에이전트가 담당 직원의 약 6배에 해당하는 시간 동안 일했다고도 밝혔어요.",
          "content": "Anthropic이 자사의 고용이 어떻게 달라지고 있는지 정리한 경제 연구 보고서를 냈어요. 아래 수치는 모두 Anthropic 내부 수치이고, 다른 기업이나 업계 전체에 대한 통계가 아니에요.\n\n보고서에 따르면 Anthropic 기술 부서에서 주니어급 직원이 차지하는 비중은 2025년 초 이후 21%에서 14%로 줄었어요. 주니어 기술 인력의 채용 비중은 더 빠르게 줄어 27%에서 9%가 됐어요. 보고서는 이 고용 비중 변화를 눈에 띄는 변화라고 표현했어요.\n\n에이전트 활용도 다뤄요. 보고서는 8월까지 직원 개인이 배치한 에이전트가 일한 시간이 담당 직원이 일한 시간의 6배였다고 밝혔어요. 보고서 요약에서는 이를 상호작용형 에이전트 사용 시간이 직원 시간의 6배라고 적어요.\n\n이 보고서는 Anthropic이 같은 날 낸 기대 격차 설문 보고서와 함께 개요 페이지로 묶여 있어요.",
