          "platform": "Web",
          "title": "Claude Code 2.1.301·302, 재시도 대기 상한과 분류 모델 지정 추가",
          "deck": "무인 재시도 대기 제한, OTel 필드, Claude Design 종료 안내가 들어갔어요",
          "summary": "Claude Code 2.1.301은 무인 재시도 모드가 먼 사용량 한도 초기화를 기다리지 않고 요청을 끝내는 환경 변수와 OpenTelemetry 이벤트 필드를 추가했어요. 2.1.302는 자동 모드 분류기의 모델을 고르는 환경 변수와 /config의 Idle compaction 항목을 더했어요.",
          "content": "Claude Code 공식 GitHub 릴리스 노트에 연이어 올라온 두 버전의 변경 사항이에요. GitHub 게시 시각(UTC) 기준으로 2.1.301은 10월 15일, 2.1.302는 10월 16일에 올라왔어요.\n\n2.1.301의 변경 사항은 다음과 같아요.\n\n- 무인 재시도 모드(CLAUDE_CODE_RETRY_WATCHDOG)가 사용량 한도 초기화까지 너무 오래 걸릴 때 기다리지 않고 요청을 끝내도록 하는 환경 변수 CLAUDE_CODE_RETRY_WATCHDOG_MAX_USAGE_LIMIT_WAIT_MS가 추가됐어요.\n- OpenTelemetry의 tool_decision 이벤트에 classifier_verdict와 permission_mode 필드가 추가됐어요.\n- vim 모드에 괄호 짝으로 건너뛰는 % 이동 동작이 추가됐어요.\n\n2.1.302의 변경 사항은 다음과 같아요.\n\n- 클라이언트 쪽 자동 모드 분류기가 쓰는 모델을 고르는 환경 변수 CLAUDE_CODE_AUTO_MODE_MODEL이 추가됐어요. 릴리스 노트에는 서버 쪽 자동 모드의 모델은 바꾸지 않는다고 적혀 있어요.\n- /config에 Idle compaction 항목이 추가됐어요.\n- /design-sync와 /design-login에 독립형 Claude Design(claude.ai/design)이 2026년 12월 14일까지 종료된다는 안내가 추가됐어요.\n\n위 내용은 두 버전의 릴리스 노트 항목 가운데 일부를 옮긴 것이에요. 전체 항목은 공식 릴리스 페이지와 CHANGELOG에서 확인할 수 있어요.",
          "source": "https://github.com/anthropics/claude-code/releases/tag/v2.1.302",
          "officialUrl": "https://github.com/anthropics/claude-code/releases/tag/v2.1.302",
          "verifiedAt": "2026-10-18",
