          "en": {
            "title": "Claude Code 2.1.301 and 2.1.302 add a retry wait cap and a classifier model setting",
            "deck": "Unattended retry limits, OTel fields and a Claude Design shutdown notice are included",
            "summary": "Claude Code 2.1.301 adds an environment variable that lets unattended retry mode end a request instead of waiting for a distant usage limit reset, along with new OpenTelemetry event fields. Version 2.1.302 adds an environment variable to choose the auto mode classifier model and an Idle compaction row in /config.",
            "content": "These are the changes in two consecutive versions listed in the official Claude Code GitHub release notes. By GitHub publication time (UTC), version 2.1.301 was published on October 15 and version 2.1.302 on October 16.\n\nVersion 2.1.301 changes:\n\n- Adds the environment variable CLAUDE_CODE_RETRY_WATCHDOG_MAX_USAGE_LIMIT_WAIT_MS, so unattended retry mode (CLAUDE_CODE_RETRY_WATCHDOG) ends a request at a usage limit that resets too far away instead of waiting.\n- Adds classifier_verdict and permission_mode fields to OpenTelemetry tool_decision events.\n- Adds the vim % motion, which jumps between matching brackets.\n\nVersion 2.1.302 changes:\n\n- Adds the environment variable CLAUDE_CODE_AUTO_MODE_MODEL to choose the model the client-side auto mode classifier uses. The release notes say it does not change the model for server-side auto mode.\n- Adds an Idle compaction row to /config.\n- Adds a notice to /design-sync and /design-login that standalone Claude Design (claude.ai/design) closes by December 14, 2026.\n\nThese are some of the entries in the two release notes. The full list is on the official release pages and in the CHANGELOG."
          }
