          "title": "Anthropic, NIST ECDSA 곡선 시드의 유래를 Claude가 찾았다고 발표",
          "deck": "취약점 발견이 아니라 시드 출처 확인이라고 Anthropic은 설명해요",
          "summary": "Anthropic은 Claude가 30분이 채 안 되는 시간에 NIST ECDSA 곡선 시드가 만들어진 방식을 알아냈다고 밝혔어요. 시드는 해시 알고리즘의 결과가 아니라 C 라이브러리의 lrand48 난수 생성기에 Unix 타임스탬프를 넣어 만든 값이었다는 설명이에요. Anthropic은 이것이 암호 공격이나 약점 발견은 아니라고 덧붙였어요.",
          "content": "Anthropic이 자체 연구 페이지에서 Claude가 NIST의 P-192, P-224, P-256, P-384, P-521 곡선 시드의 유래를 30분이 채 안 되는 시간에 찾아냈다고 밝혔어요. 이 페이지는 Frontier Red Team 분류로 10월 16일에 올라왔어요.\n\nAnthropic에 따르면 이 시드들은 어떤 해시 알고리즘의 결과물도 아니었어요. C 라이브러리의 lrand48 난수 생성기가 Unix 타임스탬프를 시드로 받아 내놓은 출력이었다고 해요.\n\nAnthropic은 이 결과가 뜻하는 범위도 분명히 했어요. 암호학적 공격이나 새로운 공격 방법, ECDSA 곡선의 약점을 찾은 것이 아니라고 밝혔고, 오히려 곡선이 백도어 없이 선택됐다는 확신을 더해 준다고 적었어요.\n\n이 내용은 Anthropic이 직접 공개한 설명이며, 외부 검토 결과는 확인하지 못했어요.",
          "source": "https://www.anthropic.com/research/ecdsa-curve-origins",
          "officialUrl": "https://www.anthropic.com/research/ecdsa-curve-origins",
          "verifiedAt": "2026-10-18",
          "slug": "claude-ecdsa-curve-origins",
