          "en": {
            "title": "Anthropic says Claude found the origins of the NIST ECDSA curve seeds",
            "deck": "Anthropic describes it as finding where the seeds came from, not a weakness",
            "summary": "Anthropic says Claude worked out in under half an hour how the NIST ECDSA curve seeds were generated. According to Anthropic, they came from the C library's lrand48 generator seeded with a Unix timestamp, not from a hash algorithm. Anthropic adds that this is not a cryptographic attack or a weakness.",
            "content": "Anthropic says on its own research page that Claude discovered the origins of the NIST P-192, P-224, P-256, P-384 and P-521 seeds in under half an hour. The page was listed under Frontier Red Team on October 16.\n\nAccording to Anthropic, none of the seeds were the result of any hash algorithm. They were the output of the C library's lrand48 random-number generator, seeded with a Unix timestamp.\n\nAnthropic also set out what the result does and does not mean. It says this is not a cryptographic break, a new attack, or a weakness in the ECDSA curves, and that it makes Anthropic more confident the curves were chosen without any backdoors.\n\nThis is Anthropic's own published account, and no outside review of it has been confirmed."
          }
