          "title": "Anthropic, METR 평가팀에 직원 수준 내부 접근 제공",
          "deck": "METR은 Anthropic의 위험 수준과 관행에 대한 분석을 직접 공개해요",
          "summary": "Anthropic은 프런티어 AI 모델을 평가하는 비영리 단체 METR의 직원 6명에게 자사 위험 평가 팀과 대체로 비슷한 수준의 하드웨어, 사무 공간, 내부 도구 접근을 제공했다고 밝혔어요. METR은 분석을 직접 공개하며, Anthropic은 SecureBio, Accenture와도 협력하고 Hugging Face 등과 초기 논의 중이라고 해요.",
          "content": "Anthropic이 10월 15일 독립 평가자에 관한 업데이트를 올렸어요. 프런티어 AI 모델을 평가하는 비영리 단체 METR의 팀에게 직원에 준하는 접근 권한을 주기 시작했다는 내용이에요.\n\n회사는 METR 직원 6명에게 회사 지급 하드웨어와 사무 공간을 마련하고, 내부 도구와 시스템에 접근할 수 있게 했다고 밝혔어요. 접근 수준은 Anthropic의 자체 위험 평가 팀과 대체로 비슷하다고 설명했어요.\n\n공개 방식에 관해서는 METR이 Anthropic의 위험 수준, 사고, 관행에 대한 분석을 발표한다고 해요. Anthropic은 발표를 막을 수 없지만, 미리 정한 범주에 해당하는 정보는 가리도록 요구할 수 있다고 밝혔어요.\n\n글에는 SecureBio, Accenture와도 협력하고 있으며 Hugging Face 같은 다른 곳과는 초기 단계의 논의 중이라고 적혀 있어요. 이 글은 10월 15일과 16일에 수정됐고, SecureBio와 METR의 조건을 명확히 하는 변경이었어요. 위 내용은 모두 Anthropic의 설명이에요.",
          "source": "https://www.anthropic.com/news/an-update-on-independent-evaluators",
          "officialUrl": "https://www.anthropic.com/news/an-update-on-independent-evaluators",
          "verifiedAt": "2026-10-18",
