          "en": {
            "title": "Anthropic Gives METR Evaluators Employee-Like Access to Internal Systems",
            "deck": "METR will publish its own analysis of Anthropic's risk levels and practices",
            "summary": "Anthropic says it has given six METR employees company hardware, office space and access to internal tools and systems roughly on par with its own risk assessment teams. METR will publish its own analysis, and Anthropic says it is also working with SecureBio and Accenture and is in early talks with others such as Hugging Face.",
            "content": "On October 15, Anthropic posted an update on independent evaluators. It says the company has started to give employee-like access to a team from METR, a nonprofit that evaluates frontier AI models.\n\nThe company says it onboarded six METR employees with company hardware, office space, and access to internal tools and systems. It describes this access as roughly on par with what Anthropic's own risk assessment teams have.\n\nOn publication, the post says METR will publish its analysis of Anthropic's risk levels, incidents, or practices. Anthropic says it cannot veto publication, but it can require METR to redact information that falls into predefined categories.\n\nThe post also says Anthropic is working with SecureBio and Accenture and is in early talks with others such as Hugging Face. The page was edited on October 15 and 16 to clarify the SecureBio and METR terms. All of the above is Anthropic's own account."
          }
