          "thumbnail": {
            "src": "/source-media/weekly-20261019/d4fafcbf3d21.png",
            "alt": "Diagram titled \"If machines do most of the reading, how does anyone learn the code?\" On the left, a grid stands for the codebase, with a few squares highlighted as managed settings, the part you want to understand; nobody keeps a complete mental model of it in their head. An arrow labeled \"Ask Claude about exactly that slice\", with the example question \"How does Claude Code retrieve managed settings?\", leads to two outcomes: Claude writes an explainer, which takes minutes and reflects the code as it is today; and, for some, Claude builds a small artifact that visualizes that part of the code and teaches it the way that person likes to learn. Along the bottom: reading trivial diffs line by line, a one-line copy change teaches you almost nothing; an explainer for the module you are about to change teaches you a lot."
          },
          "en": {
            "title": "Claude Code team describes how it reviews code that agents mostly write",
            "deck": "A post on layered automated review and risk-tiered human approval",
            "summary": "The Claude Code team published an engineering post on how it reviews code when agents write most of it. It describes layered automated review and human approval that varies with risk. The team says merged pull requests more than doubled from June to September while the share reverted fell by more than 40 percent.",
            "content": "The Claude Code team published an engineering post on the Anthropic developer blog (claude.dev) about how it reviews code. It covers how the team checks changes when agents write most of the code. The post is marked as published on October 15, while the article index on claude.com lists it one day later, on October 16.\n\nThe post says the team wants to preserve human time and attention for issues only humans can solve, and to make sure automated checks catch the rest. It describes layering automated review to do this.\n\nApproval depends on risk. According to the post, a classifier sets the tier, and the tier decides whether a change needs no person, one person or two people to approve it.\n\nThe team also reports results. It says merged pull requests more than doubled from June to September and the share that was reverted fell by more than 40 percent. These figures are the Claude Code team's own statements."
          }
