          "en": {
            "title": "Claude Code 2.1.299 and 2.1.300 Add Idle Compaction and /advisor",
            "deck": "Conversations compact before the prompt cache expires, and trace spans gain OTel attributes",
            "summary": "Claude Code 2.1.299 adds idle compaction for a 200K+ token conversation left idle for about 54 minutes, plus an environment variable for @ file mentions. Version 2.1.300 adds /advisor on Claude Platform on AWS and OpenTelemetry GenAI semantic attributes on trace spans.",
            "content": "Claude Code shipped 2.1.299 and 2.1.300 on October 14. The changes listed in the GitHub release notes, by version, are:\n\n- 2.1.299: Added idle compaction in the terminal. A conversation of more than 200K tokens left idle for about 54 minutes is compacted before its one-hour prompt cache expires, so the next message does not reprocess everything.\n- 2.1.299: Added the CLAUDE_CODE_DISABLE_FILE_MENTIONS environment variable. With it set, Claude gets the paths of @ file mentions to read with its file tools, not the files' contents.\n- 2.1.300: Added /advisor on Claude Platform on AWS. No advisor runs until you pick one with /advisor, advisorModel or --advisor, and CLAUDE_CODE_DISABLE_ADVISOR_TOOL=1 turns it off.\n- 2.1.300: Added OpenTelemetry GenAI semantic-convention attributes to trace spans, such as gen_ai.provider.name.\n- 2.1.300: Added support for rewriting a workflow agent's prompt and model in the agent.spawn mod hook."
          }
