          "deck": "Managed Agents, Messages API, SDK 트레이스를 기존 OTel 도구로 봐요",
          "summary": "Anthropic이 Claude Managed Agents, Messages API, Claude SDK의 OpenTelemetry 트레이스를 공개 베타로 내놓았어요. Grafana Cloud, Honeycomb, Datadog, Langfuse 같은 도구로 에이전트의 단계를 따라갈 수 있고, 릴리스 노트에는 SDK가 일곱 개 언어에서 스팬을 내보낸다고 적혀 있어요.",
          "content": "Anthropic이 10월 14일 Claude Platform에서 OpenTelemetry(OTel) 트레이스를 보낼 수 있게 됐다고 발표했어요. Claude Managed Agents, Messages API, Claude SDK에서 나온 트레이스를 OTel을 지원하는 어떤 도구로든 보내서, 에이전트가 거치는 각 단계를 따라갈 수 있다는 내용이에요. 이 기능은 공개 베타(public beta)로 제공돼요.\n\nAnthropic은 Grafana Cloud, Honeycomb, Datadog, Langfuse 같은 도구로 트레이스를 보낼 수 있다고 소개했어요.\n\n같은 날 Claude Platform 릴리스 노트에는 Claude SDK가 Python, TypeScript, C#, Go, Java, PHP, Ruby에서 스팬을 내보낸다고 적혀 있어요.",
