          "title": "Anthropic, Claude Startups 현재 기수 마감하고 신규 신청 중단",
          "deck": "기존 참여 기업을 위한 Startup Stack과 Applied AI 세션은 이어져요",
          "summary": "Anthropic은 Claude Startups 확대 공지 페이지에 10월 13일자로 현재 기수가 가득 차 신규 신청을 받지 않는다는 갱신 문구를 달았어요. 이에 앞서 Anthropic의 스타트업 마케팅 책임자는 X에서 신청이 몰려 Team 플랜과 API 크레딧 혜택을 잠시 멈춰야 한다고 말했어요.",
          "content": "Anthropic이 10월 6일 올린 Claude Startups 프로그램 확대 공지에 10월 13일자 갱신 문구가 붙었어요. 현재 기수가 가득 찼고 지금은 신규 신청을 받지 않는다는 내용이에요. 프로그램 안내 페이지의 첫 화면에도 같은 문구가 있는데, 이 페이지에는 날짜가 적혀 있지 않아요.\n\n확대 발표 때 공지는 혜택으로 무료 Claude Team 1년(프리미엄 좌석 최대 5개), 1회성 API 크레딧 1,000달러, 최대 4만 5천 달러 상당의 Startup Stack 할인을 소개했어요.\n\n혜택 중단에 관한 언급은 공식 페이지가 아니라 Anthropic 스타트업 마케팅 책임자의 X 게시물에 나와요. 이 책임자는 10월 9일(UTC) 게시물에서 처음 48시간 동안 받은 신청 수가 이전 5개월과 비교해 21배라며, Team 플랜과 API 크레딧 혜택 제공을 잠시 멈춰야 한다고 말했어요. 21배라는 수치는 본인의 설명이며 독립적으로 확인된 값이 아니에요. 공식 공지 페이지가 알려 주는 내용은 현재 기수 마감과 신규 신청 중단이고, 혜택 중단은 그 페이지에 적혀 있지 않아요.\n\n프로그램 안내 페이지의 FAQ에 따르면 프로그램은 현재 참여 중인 기업을 대상으로 계속돼요. Startup Stack과 Applied AI 세션도 기존 참여 기업에는 이어진다고 해요.",
