          "content": "Apple은 2026년 10월 13일 보도자료를 통해 새 Apple TV 4K(4세대)를 공개했어요. 이번 기기에서 가장 눈에 띄는 부분은 Siri AI예요. Apple은 Siri AI를 차세대 Apple Intelligence를 기반으로 한 완전히 새로운 버전의 Siri라고 소개했어요.\n\nApple은 Siri AI가 개인 맥락을 이해하고 폭넓은 세상 지식을 갖췄으며, 시스템 전반에서 더 많은 앱 동작을 수행할 수 있는 대화형 비서라고 설명했어요. 이 설명은 Apple의 소개 문구이고, 독립적으로 검증된 결과는 아니에요.\n\nSiri AI는 tvOS 27.2에서 베타로 제공돼요. 출시 시점에 Siri AI를 영어로 쓸 수 있는 지역은 미국, 호주, 캐나다, 인도, 뉴질랜드, 싱가포르, 남아프리카공화국, 영국 8곳이고, Apple은 제품 각주에 이 목록을 적었어요.\n\n새 Apple TV 4K의 미국 가격은 299달러이고 출시일은 11월 13일이에요. AI 기능이 하드웨어 출시와 함께 소개됐고 제공 범위가 지역마다 다르기 때문에, 사용하려는 지역이 위 목록에 있는지 먼저 확인하는 편이 좋아요.",
