          "title": "Archon Robotics, 휴머노이드 탁구 복식 PingpongDuo 논문 공개",
          "deck": "로봇 두 대가 서로 부딪히지 않고 복식을 치도록 한 연구예요",
          "summary": "PingpongDuo는 휴머노이드 로봇 두 대가 탁구 복식을 치도록 한 계층형 프레임워크예요. 저자들은 시뮬레이션에서 공 받아치기 성공률이 13.2% 높았고 실제 로봇 두 대가 10회가 넘는 연속 타격을 이어 갔다고 밝혔어요.",
          "content": "PingpongDuo는 Archon Robotics 프로젝트 페이지와 arXiv에 소개된 연구로, 휴머노이드 로봇 두 대가 탁구 복식을 치도록 만든 계층형(hierarchical) 프레임워크예요. 저자들은 동료 로봇의 위치를 다루는 학습형 안전 필터로 팀 협응을 안전하게 유지한다고 설명했어요. 9쪽 분량의 프리프린트이며 동료 심사를 거치지 않았어요.\n\n초록(abstract)에서 저자들은 시뮬레이션에서 기존 최고 수준 기준 모델보다 공 받아치기 성공률이 13.2% 높았다고 밝혔어요. 실제 로봇 두 대가 엄격하게 번갈아 가며 10회가 넘는 연속 타격을 이어 갔다고도 적었어요. 이 밖에 로봇 한 대가 2.15m를 비켜서고 복귀하는 동작 주기(clearance-and-recovery cycle)를 2.4초에 마쳤다는 수치도 담겨 있어요.",
