          "content": "Artificial Analysis는 2026년 10월 13일 Decision Index v1.0을 공개했어요. 이 지표는 구조화된 결정을 한 번의 호출로 답하고 각 선택지에 확률을 붙이는 새로운 종류의 모델, 의사결정 모델(decision models)을 평가해요.\n\n지표는 AA-Omniscience-Decision, HLE-MultiChoice, When2Call, WildGuardTest 네 가지 평가를 25%씩 합산해요.\n\nArtificial Analysis는 Jev 1.13이 58점으로 선두이고, GLiDE와 Microsoft-Decision-1이 나란히 54점이라고 밝혔어요. 이 점수는 회사가 직접 측정한 값이에요.",
