            "content": "On October 13, 2026, Artificial Analysis launched the Decision Index v1.0. The index benchmarks decision models, a new category of models that answer structured decisions in a single call with a probability for each option.\n\nThe index combines four evaluations at 25% each: AA-Omniscience-Decision, HLE-MultiChoice, When2Call, and WildGuardTest.\n\nArtificial Analysis says Jev 1.13 leads with 58, ahead of GLiDE and Microsoft-Decision-1, both on 54. These scores are the company's own measurements."
