          "title": "Artificial Analysis, FrontierCode 순위 추가",
          "deck": "100개 과제로 메인테이너가 병합할 만한 코드인지 쟀어요",
          "summary": "Artificial Analysis가 Cognition이 만든 코딩 벤치마크 FrontierCode 1.1을 자사 순위표에 추가했어요. 회사는 Claude Opus 5.5가 평균 점수 52%로 선두이고, GPT-6.1 Sol과 Claude Fable 5.1이 49%라고 밝혔어요.",
          "content": "Artificial Analysis는 2026년 10월 12일 Cognition이 오픈소스 저장소 메인테이너들과 함께 만든 코딩 벤치마크 FrontierCode를 순위표에 추가했다고 발표했어요. 글 제목은 AI 모델이 메인테이너가 병합할 만한 코드를 쓸 수 있는지 묻고 있어요.\n\nArtificial Analysis는 FrontierCode 1.1 Main 세트의 100개 과제를 과제당 3번씩 시도하게 했고, 자사의 Stirrup 하니스에서 실행했다고 밝혔어요.\n\n결과에서는 Claude Opus 5.5(max with fallback)가 평균 점수 52%로 가장 높아요. 이 모델은 시도의 58%에서 모든 필수 검사(blocking check)를 통과했어요. 그 뒤를 GPT-6.1 Sol(max)과 Claude Fable 5.1(max with fallback)이 49%로 따라요. Artificial Analysis는 선두 모델도 여전히 40% 넘게 실패한다고 짚었어요.\n\n이 수치는 Artificial Analysis가 직접 측정한 결과예요. 벤치마크 자체는 Cognition이 만들었으므로, 점수를 읽을 때 이 점을 함께 고려하시면 좋아요.",
          "source": "https://artificialanalysis.ai/articles/frontiercode",
          "officialUrl": "https://artificialanalysis.ai/articles/frontiercode",
          "verifiedAt": "2026-10-18",
          "slug": "aa-frontiercode-benchmark",
