          "summary": "Black Forest Labs가 10월 15일 5.6B 파라미터 오픈 웨이트 모델 FLUX 3 Image Klein을 공개했어요. 텍스트 이미지 생성, 이미지 편집, 최대 10장 참조 이미지를 쓰는 생성을 지원하고, 연 매출 500만 달러 미만이면 FLUX Kommunity License에 따라 상업적으로 무료로 쓸 수 있어요.",
          "content": "Black Forest Labs(BFL)가 10월 15일 FLUX 3 Image Klein을 공개했어요. 5.6B 파라미터 오픈 웨이트 모델로, 텍스트로 이미지 만들기, 이미지 편집, 최대 10장의 참조 이미지를 쓰는 멀티 레퍼런스 생성을 한 모델에서 지원한다고 밝혔어요. BFL API로도 쓸 수 있다고 해요.\n\n모델은 베이스와 스텝 증류(step-distilled) 두 가지로 나왔어요. 라이선스는 FLUX Kommunity License이고, BFL에 따르면 연 매출이 500만 달러 미만인 개인과 기업은 상업적으로도 무료로 쓸 수 있어요. Hugging Face의 가중치 저장소는 접근 신청이 필요한 gated 저장소예요. 저장소 자체는 10월 13일에 만들어졌지만, BFL 공식 발표일은 10월 15일이에요.\n\nBFL은 내부 평가에서 FLUX 3 Image Klein이 텍스트 이미지 생성, 멀티 레퍼런스 생성, 이미지 편집 세 분야 모두 1위이고, 더 큰 오픈 웨이트 모델보다 앞선다고 밝혔어요. 이 순위는 독립 기관의 평가가 아니라 회사 내부 평가 결과예요.\n\n같은 날 Hugging Face도 블로그에서 Diffusers 라이브러리 연동을 소개하는 글을 올렸어요. 연동 글과 BFL 제품 페이지 링크는 보조 자료로 함께 달았어요.",
