            "deck": "One model for text-to-image, editing and generation from up to 10 references",
            "summary": "Black Forest Labs released FLUX 3 Image Klein on October 15, a 5.6B-parameter open-weights model for text-to-image, editing and multi-reference generation, with a base and a distilled checkpoint and BFL API access. BFL says it ranks first in its internal evaluations; commercial use is free below 5 million US dollars in annual revenue under the FLUX Kommunity License.",
            "content": "On October 15, Black Forest Labs (BFL) released FLUX 3 Image Klein. BFL describes it as a 5.6B-parameter open-weights model that handles text-to-image generation, image editing and multi-reference generation with up to 10 reference images in one model. BFL says it is also available through the BFL API.\n\nThe model comes as a base model and a step-distilled model. The license is the FLUX Kommunity License, and according to BFL, individuals and companies with annual revenue under 5 million US dollars can use it commercially for free. The Hugging Face weights repository is gated and requires an access request. The repository itself was created on October 13, but BFL's official announcement date is October 15.\n\nBFL says that in its internal evaluations FLUX 3 Image Klein ranks first in text-to-image, multi-reference generation and image editing, ahead of larger open-weights models. This ranking comes from the company's own internal evaluation, not from an independent body.\n\nOn the same day, Hugging Face also published a blog post about the Diffusers integration. Links to that post and to the BFL product page are attached as supporting material."
