            "content": "On October 12, Cartesia published a blog post describing its work with Raise Financial Services, an Indian fintech group. According to Cartesia, Raise is developing multilingual voice experiences with Cartesia and has been investing heavily in building AI for Indian financial markets.\n\nCartesia says its models currently power a portion of the Dhan voice bot's interactions, including conversational KYC. By the company's own figures, more than 75% of these interactions happen in languages other than English, and Hindi alone accounts for more than half. The post also says Sonic supports 11 Indic languages.\n\nThe post is a customer and design-partner story, not an announcement of a new model or feature. The usage share and language mix are numbers reported by Cartesia and have not been independently verified. It shows what kinds of conversations a speech synthesis model handles in a financial service where many users speak languages other than English."
