          "deck": "더 높은 입찰과 법원 승인에 따라 조건이 달라질 수 있어요",
          "summary": "Character.AI 사건의 채무자 Character Technologies가 낸 파산 신청서는 디즈니가 CEO를 포함한 인력 대부분을 채용하기로 했고, 현금 2,000만 달러를 내는 기준 입찰자라고 밝혔어요. 제안을 받은 직원 대부분이 수락했다고 적었지만, 더 높은 입찰과 법원 승인이 남아 있어요.",
          "content": "2026년 10월 13일 델라웨어 지방 파산법원(사건번호 26-11603-BLS)에 Character Technologies, Inc.가 낸 신청서(Doc 15)에는 Disney Worldwide Services, Inc.를 기준 입찰자(stalking horse purchaser)로 지정하는 승인을 요청하는 내용이 담겼어요. Character Technologies는 이 사건의 채무자예요.\n\n신청서에 따르면 2026년 9월 18일에 서명된 EPA 계약에서 디즈니는 CEO를 포함한 인력 대부분을 먼저 채용하기로 했어요. 신청서는 디즈니에서 직책을 제안받은 직원 대부분이 제안을 수락했다고도 적었어요.\n\n디즈니는 현금 2,000만 달러를 내기로 했고, 이 금액이 신청서에서 Stalking Horse Purchase Price로 불려요. 그중 750만 달러는 파산 신청 전에 이미 지급됐어요.\n\n이 입찰은 기준이 되는 입찰이라서 더 높은 입찰이 나오면 달라질 수 있고, 법원 승인도 필요해요. 위 내용은 채무자 측이 법원에 낸 문서에 적힌 주장이에요. 보도에서 언급된 구체적인 직원 수와 보수 총액은 이 신청서에서 확인되지 않았어요.",
