            "summary": "In the Character.AI case, the motion filed by debtor Character Technologies says Disney agreed to hire most of the workforce, including the CEO, and is the stalking-horse bidder paying $20 million in cash. The motion says the vast majority of employees who were offered roles accepted, but higher bids and court approval are still pending.",
            "content": "A motion filed on October 13, 2026 by Character Technologies, Inc. in the U.S. Bankruptcy Court for the District of Delaware (Case 26-11603-BLS, Doc 15) asks the court to approve designating Disney Worldwide Services, Inc. as the stalking horse purchaser. Character Technologies is the debtor in the case.\n\nThe motion says that under the EPA signed on September 18, 2026, Disney agreed to hire the majority of the workforce, including the chief executive officer, up front. It also says the vast majority of employees offered roles at Disney accepted their offers.\n\nDisney will pay $20 million in cash, which the motion calls the Stalking Horse Purchase Price. Of that amount, $7.5 million was paid before the bankruptcy filing.\n\nBecause this is a stalking-horse bid, it is subject to higher bids and court approval. The statements above are claims made by the debtor in a court filing. The specific employee count and total compensation figures cited in news reports could not be confirmed in this filing."
