          "content": "Character.AI는 2026년 10월 12일 공식 블로그에서 자발적 챕터 11 파산 절차를 시작했다고 밝혔어요. 회사는 이 절차가 법원 감독 아래 회사를 매각하는 과정을 돕기 위한 것이라고 설명했어요.\n\n블로그에 따르면 플랫폼은 지금도 정상 운영 중이에요. 다만 실행 가능한 입찰이 나오지 않으면 플랫폼은 종료 절차를 밟게 된다고 적었어요. 회사는 매각이 2026년 11월 말이나 12월 초에 마무리될 것으로 예상한다고 밝혔어요.\n\n사건 정보는 Stretto가 운영하는 사건 사이트에서 확인할 수 있어요. 이곳에는 2026년 10월 12일 델라웨어 지구(D. Del.)에서 사건번호 26-11603으로 자발적 파산 신청이 접수됐다고 적혀 있어요.\n\n인수 후보에 대해서는 로이터 보도가 있어요. 로이터는 디즈니가 일부 자산을 2,000만 달러에 사겠다는 초기 입찰자(스토킹 호스)로 나섰다고 전했어요. 이 내용은 Character.AI의 블로그 글에는 없고 로이터가 보도한 것이에요. 스토킹 호스는 법원이 주관하는 경쟁 입찰에 앞서 기준 가격을 먼저 제시하는 입찰자를 뜻해요.\n\n이번 소식은 새 제품이나 모델 발표가 아니라 회사의 재무와 법적 절차에 관한 것이에요. 블로그 글에는 회사 보도자료(Business Wire) 링크가 걸려 있어요.",
