            "content": "On its official blog on October 12, 2026, Character.AI said it has initiated a voluntary Chapter 11 bankruptcy process. The company explained that the process is meant to facilitate a court-supervised sale of the company.\n\nAccording to the blog, the platform remains up and running. It also wrote that if a workable bid is unavailable, the platform will be wound down. The company said it expects the sale to be complete by the end of November or perhaps early December 2026.\n\nCase details are on a case site run by Stretto. It states that a voluntary petition was filed on October 12, 2026 in the District of Delaware (D. Del.) under Case No. 26-11603.\n\nA Reuters report covers a possible buyer. Reuters said Disney is the initial bidder (a stalking-horse bid), at 20 million dollars for some assets. This is not in Character.AI's blog post. It comes from Reuters. A stalking-horse bidder is one that sets a baseline price before a court-run competitive bidding.\n\nThis news is about the company's finances and legal process, not a new product or model. The blog post links to the company's press release on Business Wire."
