          "content": "Cline이 10월 15일 블로그에서 NVIDIA Nemotron 3.5 Super VL을 자사 에이전트 하네스(agent harness)에서 평가한 결과를 공개했어요. 평가한 모델은 Nemotron 3.5 Super VL 120B A12B예요. Cline은 Terminal-Bench 2.1 평가에서 이 모델이 생각(thinking) 모드를 끈 상태로 Cline과 함께 61.8%를 기록했고, 이는 이 모델로 시험한 하네스 네 종 가운데 가장 높은 점수라고 밝혔어요.\n\n비교 대상인 나머지 세 하네스는 이름이 공개되지 않았고, 점수는 A 53.9%, B 51.7%, C 44.9%예요. Cline은 이 중 A와 C가 높은 추론 또는 노력(effort) 설정을 썼다고 덧붙였어요. 글 제목의 벤치마크 선두라는 표현은 Cline이 직접 붙인 것이에요.\n\nCline은 계획을 먼저 세우고 편집하게 하는 프롬프트와 정체(stall) 감지기를 성능 요인으로 꼽았지만, 토큰 절감 효과는 측정하지 않았고 계획 지시의 효과를 따로 분리해 보지도 않았다고 밝혔어요. NVIDIA 기술 블로그는 Cline을 하네스 파트너로 소개하지만 61.8% 점수는 확인해 주지 않아요.",
