            "summary": "Cline says Nemotron 3.5 Super VL 120B A12B scored 61.8% on Terminal-Bench 2.1 inside the Cline harness, the best of the four harnesses it tested. The other three harnesses are unnamed, and Cline did not isolate what explains the gain.",
            "content": "In a blog post on October 15, Cline published its evaluation of NVIDIA Nemotron 3.5 Super VL inside its own agent harness. The model evaluated was Nemotron 3.5 Super VL 120B A12B. Cline said that in its Terminal-Bench 2.1 evaluation the model scored 61.8% with Cline and thinking mode turned off, the highest score among the four harnesses it tested with this model.\n\nThe other three harnesses are unnamed, and their scores are A 53.9%, B 51.7% and C 44.9%. Cline added that harnesses A and C used high reasoning or effort settings. The benchmark-leading wording in the post title is Cline's own framing.\n\nCline credited plan-before-edit prompting and a stall detector, but said it has not measured token savings or isolated the effect of the planning instruction. The NVIDIA tech blog lists Cline as a harness partner but does not confirm the 61.8% score."
