          "deck": "새 기능이 아니라 보안 인증 현황을 정리한 공지예요",
          "summary": "ElevenLabs가 이미 보유한 인증을 갱신하고 두 가지를 새로 추가했다고 밝혔어요. 추가 항목은 ElevenProductions의 SOC 2 Type I과 FedRAMP 20x Class A예요. FedRAMP 인증은 10월 1일에 이미 발표된 내용이고, 모두 회사가 직접 밝힌 내용이에요.",
          "content": "ElevenLabs는 10월 16일 블로그에서 이미 보유한 인증을 갱신했고 두 가지를 새로 추가했다고 밝혔어요. 갱신 대상에는 ISO/IEC 42001:2023과 SOC 2 Type II가 들어 있고, 요약 기준으로 ISO, SOC 2, PCI DSS 인증이 갱신됐어요.\n\n새로 추가된 항목은 ElevenProductions에 대한 SOC 2 Type I과 FedRAMP 20x Class A예요. FedRAMP 20x Class A는 10월 1일에 별도 글로 먼저 발표된 내용이라서, 이번 글은 인증 현황을 한데 정리한 성격이 커요.\n\n이 내용은 모두 ElevenLabs가 직접 밝힌 것이고, 인증 기관의 확인 페이지를 열어 대조하지는 않았어요. 새 제품 기능이 추가된 발표는 아니에요.",
