            "summary": "ElevenLabs said it renewed certifications it already holds and added two more. The additions are SOC 2 Type I for ElevenProductions and FedRAMP 20x Class A. The FedRAMP certification had already been announced on October 1, and all statements are the company's own.",
            "content": "In a blog post on October 16, ElevenLabs said it renewed certifications it already holds and added two more. The renewals include ISO/IEC 42001:2023 and SOC 2 Type II, and the summary also lists ISO, SOC 2, and PCI DSS certifications as renewed.\n\nThe two new items are SOC 2 Type I for ElevenProductions and FedRAMP 20x Class A. FedRAMP 20x Class A was already announced in a separate post on October 1, so this post is largely a roll-up of certification status.\n\nAll of this is ElevenLabs' own statement, and no auditor page was opened to cross-check it. The post does not announce a new product feature."
