          "content": "ElevenLabs는 10월 16일 고객 사례 글에서 일본 대형 통신 사업자의 기업 솔루션 부문인 NTT Docomo Business가 ElevenAgents로 구동하는 음성 기반 커뮤니티 플랫폼을 후쿠시마현 아이즈와카마쓰에서 시범 운영하고 있다고 소개했어요.\n\n이 시범 운영은 Takeda Health Foundation과 함께하고 아이즈와카마쓰시의 협조를 받아 진행돼요. 요약에 따르면 서비스는 CONN이라는 음성 도우미이고 고령 주민을 대상으로 해요. 현장 시험은 2025년 가을에 시작됐고 초기 사용자 반응이 긍정적이었다고 ElevenLabs는 전했어요.\n\n일본어를 자연스럽게 말한다는 평가는 NTT 태스크포스 구성원의 말을 ElevenLabs가 옮긴 것이에요. 새 제품 출시가 아니라 시범 운영 사례 소개이고, NTT Docomo Business가 직접 낸 자료는 이 카드에서 확인하지 못했어요.",
