            "title": "ElevenLabs Describes NTT Docomo Business Trial of Voice AI in Aizuwakamatsu",
            "deck": "A voice-based community platform powered by ElevenAgents is in trial",
            "summary": "In a customer story, ElevenLabs says NTT Docomo Business is trialing a voice-based community platform powered by ElevenAgents in Aizuwakamatsu, Fukushima. It is a voice assistant called CONN for older residents, and field trials began in autumn 2025, so this is a trial write-up rather than a new launch.",
            "content": "In a customer story on October 16, ElevenLabs said NTT Docomo Business, the enterprise solutions arm of one of Japan's largest telecommunications providers, is trialing a voice-based community platform powered by ElevenAgents in Aizuwakamatsu, Fukushima.\n\nThe trial is run with Takeda Health Foundation and with the cooperation of Aizuwakamatsu City. According to the summary, the service is a voice assistant called CONN aimed at older residents. ElevenLabs said field trials began in autumn 2025 and early user feedback was positive.\n\nThe remarks about natural Japanese speech come from an NTT taskforce member, as reported by ElevenLabs. This is a write-up of a trial rather than a new product launch, and no material published by NTT Docomo Business itself was checked for this card."
