          "date": "10/15",
          "platform": "Web",
          "title": "ElevenLabs, 영상에 음악·효과음을 입히는 Instant Soundtracks",
          "deck": "영상을 올리면 원곡과 타임스탬프에 맞춘 효과음을 만들어요",
          "summary": "ElevenLabs가 ElevenCreative에 Instant Soundtracks를 추가했어요. 영상을 올리면 모델이 원곡 음악을 붙이고, 영상에서 효과음이 필요한 지점을 분석해 해당 타임스탬프에 맞춘 효과음을 생성해요. ElevenCreative의 Music Video Editor, ElevenMusic, Studio API에서 쓸 수 있어요.",
          "content": "ElevenLabs는 10월 15일 ElevenCreative의 새 업데이트로 Instant Soundtracks를 공개했어요. 회사 설명에 따르면 사용자가 영상을 업로드하면 모델이 그 영상에 어울리는 원곡 음악을 붙이고, 영상을 분석해 효과음이 필요한 지점을 찾은 뒤 그 타임스탬프에 맞춰 효과음을 생성해요. 블로그는 이 기능을 ElevenCreative에 올린 모든 영상에 사운드트랙과 동기화된 효과음을 만들어 주는 기능으로 소개해요.\n\n이 기능은 ElevenCreative의 Music Video Editor, ElevenMusic, Studio API에서 사용할 수 있다고 안내했어요. Studio API에는 add_sfx, separate_tracks, use_audio_as_reference라는 새 매개변수가 추가됐고, 트랙 분리와 오디오 참조를 위한 옵션이 여기에 포함돼 있어요.\n\n한 번에 처리할 수 있는 분량에는 제한이 있어요. 요청 하나당 영상은 최대 10개이고, 합계 200MB와 10분 이내여야 해요.\n\n블로그 글은 10월 15일에 게시됐고 페이지에는 게시 이후 갱신 표시가 있어요. 위 내용은 확인 시점의 안내를 기준으로 했어요. 생성된 음악과 효과음의 품질이나 영상과의 동기화 정확도를 독립적으로 비교한 결과는 이 글에 포함돼 있지 않아요.",
          "source": "https://elevenlabs.io/blog/introducing-instant-soundtracks",
          "officialUrl": "https://elevenlabs.io/blog/introducing-instant-soundtracks",
