          "en": {
            "title": "ElevenLabs Launches Instant Soundtracks to Add Music and Sound Effects to Video",
            "deck": "Upload a video and get original music plus sound effects aligned to timestamps",
            "summary": "ElevenLabs added Instant Soundtracks to ElevenCreative. After a video is uploaded, the model scores it with original music, analyzes the footage for sound effect cues, and generates sound effects aligned to those timestamps. It is available in the ElevenCreative Music Video Editor, ElevenMusic, and the Studio API.",
            "content": "On October 15, ElevenLabs launched Instant Soundtracks as a new update to ElevenCreative. According to the company, a user uploads a video, the model scores it with original music, then analyzes the footage for sound effect cues and generates sound effects aligned to those timestamps. The blog presents it as a way to generate a soundtrack and synchronized sound effects for any video you upload in ElevenCreative.\n\nThe company says the feature is available in the ElevenCreative Music Video Editor, ElevenMusic, and the Studio API. The Studio API gains new parameters named add_sfx, separate_tracks, and use_audio_as_reference, which include options for separating tracks and using audio as a reference.\n\nThere are limits on how much can be processed at once. Each request can include up to 10 videos, combined up to 200 MB and 10 minutes of video.\n\nThe blog post was published on October 15, and the page shows an update mark made after publication. The details above reflect the page as checked. The post does not include an independent comparison of the quality of the generated music and sound effects or of how accurately they sync to the video."
          }
