          "title": "ElevenLabs가 만든 AI 음성으로 영국 상원 연설",
          "deck": "본인 목소리를 복원해 상원 법안 심의에서 직접 발언했다고 밝혔어요",
          "summary": "ElevenLabs는 척수성 근위축증이 있는 Baroness Campbell of Surbiton이 ElevenLabs가 만든 자신의 AI 복원 음성으로 영국 상원에서 연설했다고 밝혔어요. ElevenLabs와 BBC 보도 제목은 영국 의회 토론에서 AI 생성 음성이 쓰인 첫 사례라고 소개해요.",
          "content": "ElevenLabs는 10월 13일 블로그에서 Baroness Campbell of Surbiton이 영국 상원(House of Lords)에서 자신의 목소리로 연설했다고 소개했어요. 연설은 Health Bill의 제2독회(Second Reading) 중에 이뤄졌고, ElevenLabs가 만든 본인 목소리의 AI 복원 음성이 쓰였어요. 연설 주제는 그가 여러 해 동안 캠페인으로 이어 온 사안의 핵심이었다고 해요.\n\nElevenLabs 설명에 따르면 이 음성은 그가 과거에 말하는 모습을 담은 클립을 업로드해 만들었어요. 페이지에는 상원 의장(Lord Speaker)이 이 사용에 대해 언급했다는 내용도 있어요.\n\nElevenLabs는 영국 의회의 상원의원이나 하원의원이 양원 중 어느 쪽에서든 AI 생성 음성으로 발언한 것은 이번이 처음이라고 밝혔어요. BBC도 영상 페이지 제목에서 영국 의회 토론에 AI 생성 음성이 처음 쓰였다고 소개했어요. 다만 이 처음이라는 표현은 ElevenLabs의 설명과 BBC 보도 제목에 근거한 것이고, 의회 공식 기록으로 따로 확인한 내용은 아니에요.\n\n이 글은 ElevenLabs가 고객 사례로 소개한 내용이라, 음성 복원 과정과 사용 경위에 관한 설명은 ElevenLabs 페이지에 기대고 있어요.",
          "source": "https://elevenlabs.io/blog/first-ever-ai-voiced-speech-uk-parliament",
