          "title": "GitHub, 코드 스캐닝 경고용 에이전트 자동 수정 정식 출시",
          "deck": "경고를 Copilot에 맡기면 CodeQL로 다시 확인한 초안 PR이 열려요",
          "summary": "GitHub가 코드 스캐닝 경고를 위한 에이전트형 자동 수정(agentic autofix)을 정식 출시했어요. 경고를 Copilot에 할당하면 수정안을 만들고 CodeQL을 다시 실행한 뒤 초안 풀 리퀘스트를 열어요. GitHub Enterprise Cloud의 Code Security 또는 GHAS 고객이 대상이며 AI 크레딧을 사용해요.",
          "content": "GitHub는 10월 15일 변경 내역에서 코드 스캐닝 경고용 에이전트 자동 수정이 정식 출시(GA)됐다고 밝혔어요. 경고를 Copilot에 할당하면 개발자가 하는 방식대로 코드베이스에서 관련 파일을 살피고, 수정안을 제안하고, CodeQL을 다시 실행한 뒤 초안 풀 리퀘스트를 열어요.\n\n이 기능은 GitHub Enterprise Cloud에서 GitHub Code Security 또는 GHAS를 쓰는 고객에게 제공돼요. 사용하려면 엔터프라이즈 정책이 필요하고, Code Security 예산의 AI 크레딧과 GitHub Actions 사용 시간(minutes)이 함께 소모돼요.\n\n수정 내용은 초안 풀 리퀘스트로 올라오기 때문에 병합하기 전에 검토할 수 있어요.",
          "source": "https://github.blog/changelog/2026-10-15-agentic-autofix-for-code-scanning-alerts-general-availability/",
          "officialUrl": "https://github.blog/changelog/2026-10-15-agentic-autofix-for-code-scanning-alerts-general-availability/",
          "verifiedAt": "2026-10-18",
          "slug": "github-agentic-autofix-code-scanning-ga",
          "tags": [
            "AI",
            "2026-w42",
            "GitHub",
            "Security"
          ],
          "thumbnail": {
            "src": "/source-media/weekly-20261019/63333daa9b8c.png",
            "alt": "A view of a code scanning alert with the title \"Uncontrolled command line\" in large text at the top. A cursor hovers over an \"Assign to Copilot\" button in the Assignees section."
          },
          "en": {
            "title": "GitHub makes agentic autofix for code scanning alerts generally available",
            "deck": "Assign an alert to Copilot and get a CodeQL-checked draft PR",
            "summary": "GitHub says agentic autofix for code scanning alerts is generally available. Assigning an alert to Copilot produces a fix that is re-checked with CodeQL and opened as a draft pull request. It requires GitHub Enterprise Cloud with Code Security or GHAS, an enterprise policy, and it consumes AI Credits.",
            "content": "On October 15, GitHub said in its changelog that agentic autofix for code scanning alerts is now generally available. When an alert is assigned to Copilot, it works the way a developer would: it explores the relevant files in the codebase, proposes a fix, reruns CodeQL, and opens a draft pull request.\n\nThe feature is available to customers of GitHub Code Security or GHAS on GitHub Enterprise Cloud. It needs an enterprise policy, and it consumes AI Credits from your Code Security budget as well as GitHub Actions minutes.\n\nBecause the fix arrives as a draft pull request, it can be reviewed before it is merged."
          }
