          "deck": "CodeQL이 다루지 않는 언어의 취약점을 AI로 찾아 알려 줘요",
          "summary": "GitHub가 풀 리퀘스트용 코드 스캐닝 AI Scan을 정식 출시했어요. CodeQL이 지원하지 않는 언어와 프레임워크의 취약점을 AI로 찾아 주고, 결과는 참고용이라 병합을 막지 않아요. 비공개 조직 저장소는 Code Security 또는 GHAS가 필요해요.",
          "content": "GitHub는 10월 15일 풀 리퀘스트용 코드 스캐닝 AI Scan이 정식 출시됐다고 밝혔어요. AI Scan은 CodeQL이 현재 지원하지 않는 언어와 프레임워크에서 풀 리퀘스트 변경 사항의 취약점을 찾아 CodeQL을 보완해요.\n\nGitHub가 예로 든 대상은 PHP, Shell/Bash, Terraform 구성(HCL), Dockerfile, Java용 JSP, C#용 Blazor예요.\n\nAI Scan의 결과는 참고용(advisory)이에요. 코드 스캐닝 검사를 실패시키지 않고, 풀 리퀘스트 병합을 막을 수도 없어요. 비공개 또는 내부 조직 저장소에서 쓰려면 GitHub Code Security 또는 GHAS가 필요하고, GitHub Copilot 라이선스는 필요하지 않아요.",
          "source": "https://github.blog/changelog/2026-10-15-ai-scan-for-pull-requests-generally-available/",
