          "deck": "Claude Opus 4.8, Opus 5, GPT-5.6 Terra가 대상이에요",
          "summary": "GitHub가 2026년 11월 16일부로 Claude Opus 4.8, Claude Opus 5, GPT-5.6 Terra를 모든 Copilot 환경에서 지원 중단한다고 예고했어요. 대체 모델로 Claude Opus 5.5, GPT-6.1 Sol, GPT-6 Luna를 안내했고, Opus 4.8은 연간 요금제 개인 구독자에게 계속 제공돼요.",
          "content": "GitHub는 10월 15일 변경 내역에서 2026년 11월 16일에 Copilot의 일부 모델을 지원 중단한다고 예고했어요. 대상 범위는 Copilot Chat, 인라인 편집, ask와 agent 모드, 코드 완성을 포함한 모든 Copilot 환경이에요.\n\n지원 중단 대상은 세 가지예요.\n\n- Claude Opus 4.8\n- Claude Opus 5\n- GPT-5.6 Terra\n\nGitHub가 표에 적은 대체 모델은 Claude Opus 5에는 Claude Opus 5.5, GPT-5.6 Terra에는 GPT-6.1 Sol 또는 GPT-6 Luna예요.\n\n예외도 있어요. Claude Opus 4.8은 연간 요금제를 쓰는 개인 Copilot 구독자에게는 계속 제공된다고 GitHub는 밝혔어요.",
