            "deck": "Claude Opus 4.8, Claude Opus 5, and GPT-5.6 Terra are affected",
            "summary": "GitHub announced that Claude Opus 4.8, Claude Opus 5, and GPT-5.6 Terra will be deprecated across all Copilot experiences on November 16, 2026. It names Claude Opus 5.5, GPT-6.1 Sol, and GPT-6 Luna as alternatives, and Opus 4.8 stays available to individual subscribers on annual plans.",
            "content": "On October 15, GitHub announced in its changelog that it will deprecate some Copilot models on November 16, 2026. The change covers all GitHub Copilot experiences, including Copilot Chat, inline edits, ask and agent modes, and code completions.\n\nThree models are affected.\n\n- Claude Opus 4.8\n- Claude Opus 5\n- GPT-5.6 Terra\n\nIn its table, GitHub lists Claude Opus 5.5 as the alternative to Claude Opus 5, and GPT-6.1 Sol or GPT-6 Luna as the alternative to GPT-5.6 Terra.\n\nThere is one exception. GitHub says Claude Opus 4.8 will remain available to individual GitHub Copilot subscribers on annual plans."
