          "deck": "한 대화에서 여러 저장소의 이슈와 PR을 다뤄요",
          "summary": "GitHub가 Slack과 Microsoft Teams의 @GitHub가 한 대화 안에서 여러 저장소를 다룰 수 있게 됐다고 밝혔어요. 메시지 어디서나 멘션하기, Slack 스레드 맥락 개선 같은 작은 개선도 함께 올라왔고, 제공 요금제는 글에 나와 있지 않아요.",
          "content": "GitHub는 10월 15일 변경 내역에서 Slack과 Microsoft Teams의 @GitHub가 한 대화 안에서 여러 저장소에 걸쳐 일할 수 있게 됐다고 밝혔어요. 이슈를 만들고, 풀 리퀘스트를 열고, 버그를 조사하는 작업이 대상이에요.\n\n함께 소개된 개선은 다음과 같아요.\n\n- 메시지의 어느 위치에서든 @GitHub를 멘션할 수 있어요.\n- Slack 스레드의 맥락을 더 잘 가져와요.\n- 안정성과 관련된 수정이 들어갔어요.\n\n글에는 어떤 요금제에서 쓸 수 있는지가 적혀 있지 않고, 본문에 새 모델에 관한 내용도 없어요.",
