            "content": "On October 15, GitHub said in its changelog that @GitHub in Slack and Microsoft Teams now supports working across multiple repositories in a single conversation. It covers creating issues, opening pull requests, and investigating bugs.\n\nThe post also lists these improvements.\n\n- You can mention @GitHub anywhere in a message.\n- It picks up better context from Slack threads.\n- Reliability fixes are included.\n\nThe post does not say which plans can use the feature, and its body contains no new model."
