          "summary": "GitHub Copilot CLI 1.0.98은 Gemini 4 Argon 지원과 훅, MCP 상태, 세션 재개 관련 수정을 담았어요. 다음 날 올라온 프리릴리스 1.0.99-0은 샌드박스가 로컬 네트워크 접근을 기본으로 허용해요.",
          "content": "GitHub Copilot CLI가 10월 14일에 1.0.98을, 10월 15일에 프리릴리스 1.0.99-0을 공개했어요. 두 릴리스의 변경 사항은 GitHub 릴리스 노트에 적힌 내용이에요.\n\n1.0.98은 10월 14일에 올라온 정식 릴리스예요. 변경 사항은 다음과 같아요.\n\n- Gemini 4 Argon 지원을 추가했어요.\n- Node 환경에서 자식 프로세스 종료 신호가 사라져도 명령 훅이 안정적으로 끝나요.\n- 화면 분할로 세션을 바꾼 뒤에도 MCP 상태와 /mcp 명령이 활성 세션과 맞춰져요.\n- 세션을 재개할 때 중단된 권한 승인 대기 작업을 반영하도록 고쳤어요.\n\n1.0.99-0은 10월 15일에 올라온 릴리스로, 프리릴리스(Pre-release)로 표시돼 있어요. 변경 사항은 다음과 같아요.\n\n- 샌드박스가 기본적으로 로컬 네트워크 접근을 허용해서, 명령이 localhost와 사설 네트워크 서비스에 닿을 수 있어요.\n- /share 동작 메뉴를 추가했어요.\n- /sandbox를 한 세션 동안 켜 두는 모드를 추가했어요.\n- 브라우저 플러그인 이름을 browser-use로 바꿨어요.\n\n1.0.99-0은 프리릴리스 버전이라, 정식 버전에 같은 변경이 어떻게 들어갈지는 확인되지 않았어요.",
