            "title": "GitHub Copilot CLI 1.0.98 and the 1.0.99-0 pre-release",
            "deck": "Gemini 4 Argon support and a new sandbox network default",
            "summary": "GitHub Copilot CLI 1.0.98 adds Gemini 4 Argon support and fixes for hooks, MCP status and session resume. The next-day pre-release 1.0.99-0 makes the sandbox allow local network access by default.",
            "content": "GitHub Copilot CLI published 1.0.98 on October 14 and the pre-release 1.0.99-0 on October 15. The changes below come from the GitHub release notes.\n\n1.0.98 is the stable release published on October 14. It changes the following.\n\n- Adds support for Gemini 4 Argon.\n- Command hooks complete reliably even when child-exit signals are lost under Node.\n- MCP status and the /mcp commands stay synced to the active session after split-view session switches.\n- Resumed sessions now respect abandoned pending-permission work.\n\n1.0.99-0 was published on October 15 and is marked Pre-release. It changes the following.\n\n- The sandbox allows local network access by default, so commands can reach localhost and private-network services.\n- Adds a /share action menu.\n- Adds a mode that keeps /sandbox on for one session.\n- Renames the browser plugin to browser-use.\n\nBecause 1.0.99-0 is a pre-release, it is not confirmed how these changes will land in a stable version."
