          "summary": "GitHub가 Copilot의 HydraFusion을 업데이트하고 새 HydraFusion Max 옵션을 더했어요. 두 옵션은 VS Code, Copilot 앱, Copilot CLI에서 리서치 프리뷰로 제공되며, 실험 또는 프리뷰 기능을 켜야 해요.",
          "content": "GitHub가 Copilot의 HydraFusion을 업데이트하고 HydraFusion Max라는 새 옵션을 더했어요. GitHub는 HydraFusion이 모델 풀을 갱신하고 오케스트레이션 워크플로를 개선했다고 밝혔어요. 모델 풀에는 Claude Opus 5.5, GPT-6 Astra, GPT-6.1 Sol, GPT-6 Luna가 쓰인다고 설명했어요.\n\n기존 옵션과 새 Max 옵션은 모두 VS Code, GitHub Copilot 앱, Copilot CLI에서 쓸 수 있어요. 두 옵션 모두 리서치 프리뷰 상태로 남아 있어요.\n\n대상 요금제는 Copilot Pro, Pro+, Business, Enterprise이고, 실험적 또는 프리뷰 기능을 켜야 쓸 수 있어요. HydraFusion은 2026년 9월 4일에 Project HydraFusion 글로 먼저 소개된 프로젝트이며, 이번 글은 그 이후의 변경 사항을 다뤄요.",
