            "content": "GitHub updated HydraFusion in Copilot and added a new option called HydraFusion Max. GitHub said HydraFusion has an updated model pool and improved orchestration workflows. It described the pool as drawing from Claude Opus 5.5, GPT-6 Astra, GPT-6.1 Sol and GPT-6 Luna.\n\nBoth the existing option and the new Max option are available in VS Code, the GitHub Copilot app and the Copilot CLI. Both remain in research preview.\n\nThe plans are Copilot Pro, Pro+, Business and Enterprise, and experimental or preview features must be enabled. HydraFusion was first introduced in the Project HydraFusion post of September 4, 2026, and this post covers the changes since then."
