          "title": "GitHub, 보안 개요에 AI Scan 지표 추가",
          "deck": "AI Scan의 탐지와 해결 현황을 관리자가 한곳에서 봐요",
          "summary": "GitHub가 보안 개요(security overview)에 AI Scan 지표를 추가해, 관리자가 탐지 건수와 해결 비율, 자동 수정 사용 현황을 확인할 수 있게 했어요. 기능은 퍼블릭 프리뷰이며 GitHub Enterprise Server는 지원하지 않아요.",
          "content": "GitHub가 보안 개요(security overview)에 AI Scan 지표를 추가했어요. GitHub는 조직과 엔터프라이즈 관리자가 풀 리퀘스트에 적용되는 AI Scan의 효과를 이제 확인할 수 있다고 밝혔어요.\n\n보여주는 지표는 AI Scan이 만들어 낸 탐지 결과와 해결된 결과, 해결 비율(remediation rate), 자동 수정(autofix) 사용 현황이에요. AI Scan을 쓰는 조직이 실제로 얼마나 문제를 고치고 있는지 숫자로 살펴볼 수 있어요.\n\n이 기능은 퍼블릭 프리뷰예요. GitHub Enterprise Cloud를 포함한 github.com에서 GitHub Code Security 또는 Advanced Security를 쓰는 고객이 대상이에요. GitHub Enterprise Server는 지원하지 않는다고 GitHub가 밝혔어요.",
          "source": "https://github.blog/changelog/2026-10-13-code-scanning-ai-scan-metrics-in-security-overview/",
