            "title": "GitHub adds AI Scan metrics to security overview",
            "deck": "Admins can see AI Scan findings and resolution in one place",
            "summary": "GitHub added AI Scan metrics to security overview so administrators can see findings generated and resolved, the remediation rate and autofix use. The feature is a public preview and does not support GitHub Enterprise Server.",
            "content": "GitHub added AI Scan metrics to security overview. GitHub said organization and enterprise administrators can now observe the impact of AI Scan for pull requests.\n\nThe metrics cover findings that AI Scan generated and resolved, the remediation rate and autofix use. Organizations that use AI Scan can follow how many issues they actually fix.\n\nThe feature is a public preview. It is available on github.com, including GitHub Enterprise Cloud, for customers with GitHub Code Security or Advanced Security. GitHub said GitHub Enterprise Server is not supported."
