          "date": "10/13",
          "platform": "Web",
          "title": "GitHub Copilot CLI 1.0.96·1.0.97, 샌드박스와 에이전트 훅 추가",
          "deck": "샌드박스 비밀 값 마스킹과 사용자 지정 에이전트 훅이 들어왔어요",
          "summary": "GitHub Copilot CLI 1.0.96은 샌드박스 설정에서 환경 비밀 값을 제안하고 마스킹 호스트를 추가하게 했어요. 1.0.97은 사용자 지정 에이전트용 훅을 더하고 에이전트 파일이 많은 저장소에서의 탐색 문제를 고쳤어요.",
          "content": "GitHub Copilot CLI가 10월 12일 1.0.96, 10월 13일 1.0.97을 연달아 내놓았어요. 두 릴리스 노트에 적힌 변경 사항은 다음과 같아요.\n\n1.0.96 (10월 12일)\n\n- 대화형 샌드박스 설정에서 환경 비밀 값으로 보이는 항목을 제안하고, 저장하기 전에 마스킹 호스트를 추가할 수 있어요.\n- /add-dir 명령이 현재 세션 동안 추가한 디렉터리에 샌드박스 접근 권한을 줘요.\n- 모델 ID의 대소문자를 구분하지 않아요.\n- 타임라인에 각 권한 결정을 누가 내렸는지 표시해요.\n\n1.0.97 (10월 13일)\n\n- 사용자 지정 에이전트에 범위가 지정된 선언형 훅을 추가할 수 있어요.\n- 저장소가 에이전트 파일을 100개보다 많이 정의하거나 깊게 중첩해도 모든 사용자 지정 에이전트를 찾아내요.\n- /usage에 토큰 과금 방식의 AI Credits가 표시돼요.\n- JSON 출력에서 비밀 값을 가려요.",
          "source": "https://github.com/github/copilot-cli/releases/tag/v1.0.97",
          "officialUrl": "https://github.com/github/copilot-cli/releases/tag/v1.0.97",
          "verifiedAt": "2026-10-18",
          "slug": "github-copilot-cli-1-0-96-1-0-97",
