          "en": {
            "title": "GitHub Copilot CLI 1.0.96 and 1.0.97 add sandbox settings and agent hooks",
            "deck": "Secret masking in the sandbox and hooks for custom agents",
            "summary": "GitHub Copilot CLI 1.0.96 suggests environment secrets in interactive sandbox settings and lets you add masking hosts. Version 1.0.97 adds agent-scoped hooks for custom agents and fixes discovery in repositories with many agent files.",
            "content": "GitHub Copilot CLI shipped 1.0.96 on October 12 and 1.0.97 on October 13. The changes listed in the two release notes are as follows.\n\n1.0.96 (October 12)\n\n- Interactive sandbox settings suggest possible environment secrets and let you add masking hosts before saving.\n- The /add-dir command grants sandbox access to added directories for the current session.\n- Model IDs are case-insensitive.\n- A Timeline shows who made each permission decision.\n\n1.0.97 (October 13)\n\n- Agent-scoped declarative hooks can be added for custom agents.\n- All custom agents are discovered even when a repository defines more than 100 agent files or nests them deeply.\n- Token-billed AI Credits are shown in /usage.\n- Secrets are redacted in JSON output."
          }
