          "content": "Higgsfield의 변경 내역은 10월 15일 항목으로 Higgsfield Community 릴리스를 기록하고 있어요. 이번 릴리스는 Community 페이지, Ranking 탭, Creators 탭, Higgsfield Grants를 추가했다고 설명해요. 블로그는 Community를 크리에이터가 Open Project, Shots, 블로그 글을 공개하는 웹사이트의 공개 영역이라고 소개해요.\n\nHiggsfield Grants는 공개된 Open Project가 최대 200,000 생성 크레딧을 신청할 수 있는 제도예요. 신청하려면 장르나 스타일에 상관없이 길이가 1분 이상인 영상을 Open Project로 공개해야 해요. 여기서 크레딧은 Higgsfield 플랫폼에서 영상을 생성할 때 쓰는 크레딧이고, 현금 지원이 아니에요.\n\n블로그 글은 10월 17일에 올라온 설명 글이고, 출시일은 변경 내역을 기준으로 10월 15일이에요. 심사 기준이나 선정 규모에 관한 내용은 확인하지 못했어요.",
