          "content": "IBM Granite가 10월 15일 허깅페이스 블로그에서 Granite Switch 4.1을 소개했어요. 8B와 30B 두 크기의 모델이 나왔고, 허깅페이스 모델 카드에는 두 모델 모두 Apache-2.0 라이선스로 표시돼 있어요.\n\nIBM에 따르면 Granite-Switch-4.1-8B와 30B는 Decision aLoRA, Guardian aLoRA, 음성 인식 모델 Granite-Speech-5.0-Turbo-CTC를 포함하도록 구성돼 있어요. 하나의 엔드포인트에서 채팅 요청, 판단 요청, 음성 요청을 오가며 처리하는 방식이에요. IBM은 어댑터들이 기본 모델의 KV 캐시를 공유하기 때문에 하나의 GPU 구성으로 대화, 판단, 음성을 모두 처리할 수 있다고 설명해요.\n\n성능에 관한 내용은 모두 IBM이 직접 밝힌 주장이에요. 회사는 Guardian aLoRA가 안전 관련 판단 과제에서 평균적으로 Jev 1.13, Microsoft-Decision-1, GPT-Luna-Decisions, Clef-Flash보다 나은 성능을 낸다고 밝혔고, Granite-Speech-5.0-Turbo-CTC를 OpenASR 리더보드에서 가장 빠른 ASR 모델이라고 소개했어요. 이 비교와 속도 주장은 독립적으로 확인되지 않았어요.\n\n도입을 검토한다면 허깅페이스 블로그와 두 모델 카드에서 구성과 사용 조건을 직접 확인하는 편이 좋아요.",
