            "summary": "IBM Granite released Granite Switch 4.1 in 8B and 30B sizes. It combines a base model with a Decision adapter, a Guardian safety adapter and a speech-recognition model so that chat, decision and spoken requests are served from one endpoint.",
            "content": "IBM Granite introduced Granite Switch 4.1 in a Hugging Face blog post on October 15. The models come in 8B and 30B sizes, and both model cards on Hugging Face list the Apache-2.0 license.\n\nAccording to IBM, Granite-Switch-4.1-8B and 30B are configured to include a Decision aLoRA, a Guardian aLoRA and the speech recognition model Granite-Speech-5.0-Turbo-CTC. A single endpoint switches between chat requests, decision requests and spoken requests. IBM explains that the adapters share the base model's KV cache, so one GPU footprint can serve chat, decisions and speech.\n\nAll performance statements are IBM's own claims. The company says the Guardian aLoRA, on average, outperforms Jev 1.13, Microsoft-Decision-1, GPT-Luna-Decisions and Clef-Flash on safety-related decision tasks, and it describes Granite-Speech-5.0-Turbo-CTC as the fastest ASR model on the OpenASR Leaderboard. These comparisons and speed claims have not been independently checked.\n\nAnyone considering adoption should confirm the configuration and usage terms in the Hugging Face blog post and the two model cards."
