          "deck": "인텔 자체 카드는 160GB, 파트너 카드는 최대 480GB예요",
          "summary": "인텔이 AI 추론용 GPU인 Intel GPU D시리즈(코드명 Crescent Island)를 소개하며 고객 샘플링이 진행 중이라고 밝혔어요. 인텔 브랜드 PCIe 카드는 LPDDR5X 160GB이고, 최대 480GB는 파트너사가 만드는 카드의 상한이에요.",
          "content": "인텔은 OCP 2026을 맞아 낸 뉴스룸 글에서 코드명 Crescent Island인 Intel GPU D시리즈를 소개했어요. 인텔은 이 GPU가 AI 추론 워크로드용으로 설계됐다고 설명했고, 고객 샘플링이 진행 중이라고 밝혔어요. 인텔 뉴스룸 목록에는 이 글이 2026년 10월 12일자로 표시돼 있어요.\n\n인텔이 제시한 사양은 최대 480GB LPDDR5X 메모리, 초당 1.5TB 메모리 대역폭, FP8 기준 1.3페타플롭스 연산 성능이에요. 소비 전력은 350와트 범위 안이에요. 각주에 따르면 인텔 브랜드 PCIe 카드는 LPDDR5X 160GB를 탑재하고, 파트너가 ODM 브랜드 카드를 만들 때 최대 480GB까지 유연하게 구성할 수 있어요. 그래서 480GB는 파트너 카드의 최대치로 읽어야 해요.\n\n인텔 제품 페이지에는 이 제품이 Intel GPU D270이라는 이름으로 나오고, 최대 480GB LPDDR5X를 제공한다고 적혀 있어요. 다만 출시 일정은 확인되지 않아요. 지금 확인되는 상태는 고객 샘플링이 진행 중이라는 점까지예요.",
          "source": "https://www.intel.com/content/www/us/en/newsroom/news/artificial-intelligence/intel-accelerates-open-infrastructure-agentic-ai-era.html",
