          "title": "Kling AI, Kling 4.0 전면 제공 시작과 MCP·CLI 접근 발표",
          "deck": "개편된 제작 화면과 MCP, CLI로 Kling 4.0을 쓸 수 있어요",
          "summary": "Kling AI가 10월 15일 공식 X 계정에서 Kling 4.0을 전면 제공한다고 밝혔어요. 개편된 제작 화면과 MCP, CLI로 Kling 4.0에 접근할 수 있다고 안내했어요. 9월 30일 회사 블로그는 3초에서 30초까지의 영상 생성과 다중 키프레임, 다중 참조를 소개했고, 얼리 액세스는 9월 28일에 시작됐다고 밝혔어요.",
          "content": "Kling AI는 10월 15일 공식 X 계정에 올린 글에서 KLING 4.0 Is Now Fully Available이라고 알렸어요. 이날부터 달라진 점으로 개편된 제작 화면을 통한 접근, 그리고 MCP와 CLI를 통한 Kling 4.0 접근을 꼽았어요. 게시글의 첫머리 문구는 For Those Who Create예요.\n\n이번 공지는 새 모델의 첫 공개가 아니에요. Kling이 9월 30일에 올린 블로그 글에 따르면 얼리 액세스는 9월 28일에 시작됐어요. 기능 설명도 이번 X 글이 아니라 이 블로그 글에 담겨 있고, 회사는 다음과 같이 밝혔어요.\n\n- 3초에서 30초까지 네이티브 영상 생성을 지원해요.\n- 유연한 키프레임을 최대 10개까지 쓸 수 있어요.\n- 참조 자산을 합쳐서 최대 15개까지 쓸 수 있어요.\n\nX 글 미리보기에는 Coming Soon 항목으로 10-bit HDR이 적혀 있어요. 다만 미리보기 글이 일부 잘려 있어서 전체 목록은 확인하지 못했어요.\n\n10월 18일 국내 매체 AI Times는 이번 발표를 정식 출시로 보도하며 한 번에 30초 영상을 생성한다고 전했어요. 위 기능은 모두 Kling이 직접 밝힌 내용이고, 생성 품질을 다른 모델과 독립적으로 비교한 결과는 포함돼 있지 않아요.",
