          "content": "Krea가 10월 15일 블로그에서 새 이미지 편집 모델 Krea 3를 공개했어요. 회사는 오늘 출시한다고 밝혔고, krea.ai에서 3천만 명의 사용자에게 바로 제공된다고 설명했어요.\n\nKrea에 따르면 대부분의 편집은 네이티브 2K 해상도에서 처음부터 끝까지 8초 안에 돌아오고, 비용은 2K 이미지 한 장당 0.06달러예요. 편집 한 번에 참조 이미지를 최대 6장까지 쓸 수 있어요.\n\nKrea 3는 krea.ai 외에도 fal, Hedra, Together AI, Nous Research, OpenRouter, Replicate를 통해 쓸 수 있어요.\n\n속도와 Nano Banana Pro와의 비교는 Krea가 2026년 9월 24일부터 10월 1일까지 직접 측정한 값이에요. 독립적으로 검증된 수치는 확인되지 않았으므로 회사가 밝힌 값으로 읽어 주세요.",
