            "summary": "Krea released Krea 3, a new image editing model. The company says most edits finish in under 8 seconds at native 2K for $0.06 per image, and the model accepts up to six reference images.",
            "content": "Krea released its new image editing model, Krea 3, in a blog post on October 15. The company says it is releasing the model today and that it is live on krea.ai for its 30 million users.\n\nAccording to Krea, most edits come back in under 8 seconds, end to end, at native 2K resolution, and the model costs $0.06 per image at 2K. Each edit can take up to six reference images.\n\nBesides krea.ai, Krea 3 is available through fal, Hedra, Together AI, Nous Research, OpenRouter and Replicate.\n\nThe speed figures and the comparison with Nano Banana Pro are Krea's own measurements, taken from September 24 to October 1, 2026. No independent verification has been confirmed, so read these as figures reported by the company."
