          "content": "LG CNS는 2026년 10월 14일 일본의 대표 통신기업 KDDI와 아시아태평양 지역 AX·DX 사업을 위한 업무협약(MOU)을 맺고 협력 체계 구축에 나선다고 밝혔어요.\n\nAI 분야에서 두 회사는 LG CNS의 AgenticWorks 플랫폼을 바탕으로 KDDI의 아태 지역 사업에 맞춘 에이전틱 AI 서비스 개발을 모색해요. 피지컬 AI 로봇 관리(PhysicalWorks)와 스마트시티 협력은 검토 단계예요.\n\n이번 발표는 서비스 출시가 아니라 협력 의향을 담은 업무협약이에요. 거래 금액이나 일정은 보도자료에 나와 있지 않아요.",
