          "content": "Liquid AI가 10월 15일 d1-ultra를 출시했다고 밝혔어요. 회사는 이 모델을 \"our new multimodal decision model with state-of-the-art performance\", 즉 최고 수준의 성능을 가진 새로운 멀티모달 결정 모델이라고 소개해요. 입력으로 텍스트와 이미지를 받는 모델이에요.\n\n지금은 Liquid API로만 이용할 수 있고, 가격은 입력 토큰 100만 개당 0.042달러예요. Liquid AI는 곧 Vercel과 OpenRouter에서도 쓸 수 있게 하겠다고 밝혔어요. 오픈 웨이트나 라이선스는 글에 나와 있지 않아요.\n\n성능 순위는 Liquid AI의 주장이에요. 회사는 Artificial Analysis Decision Index에서 다른 결정 모델보다 최소 8점 앞선다고 썼지만, 해당 문장이 원문에서 깨져 있어서 정확한 비교 조건은 확인하지 못했어요. 페이지 제목은 이 모델을 세계 최고의 결정 모델이라고 부르지만, 이 역시 회사의 표현이에요.",
