          "content": "Liquid AI가 10월 13일 LFM2.5-24B-A2B를 공개했어요. 회사는 이 모델을 \"24B-parameter reasoning model with just 2B active parameters\", 즉 전체 24B 파라미터 중 2B만 활성화되는 추론 모델이라고 소개하며, 기기 안에서 빠르고 비공개로 돌아가는 에이전트를 위한 모델이라고 설명했어요.\n\nLiquid AI에 따르면 기본(base) 모델과 후속 학습(post-trained) 모델이 모두 오픈 웨이트이고, Hugging Face와 자사 Playground에서 바로 쓸 수 있어요. 속도와 벤치마크 수치는 회사가 직접 보고한 값이에요. 한 예로 Apple M5 Max에서 초당 184토큰이라고 밝혔는데, 제3자가 검증한 수치는 확인되지 않았어요.\n\n블로그 글에는 라이선스가 적혀 있지 않아요. Hugging Face 저장소 메타데이터에는 라이선스가 other, lfm1.0으로 표시돼 있어요. 가중치를 사용하기 전에 해당 라이선스 조건을 직접 확인하는 편이 좋아요.",
