          "summary": "Lovable이 10월 13일 에이전트 연동을 켠 앱에 WebMCP 도구를 함께 추가한다고 밝혔어요. 브라우저에 내장된 AI 에이전트가 사용자가 열어 둔 페이지에서 동작할 수 있고, 도구는 로그인한 사용자 본인의 탭에서 실행돼요.",
          "content": "Lovable은 변경 기록(changelog)에 2026년 10월 13일자로 브라우저 에이전트가 앱을 사용하게 하는 기능을 올렸어요. 에이전트 연동을 켜면 Lovable이 앱에 WebMCP 도구도 함께 추가하고, 브라우저에 내장된 AI 에이전트가 사용자가 열어 둔 페이지에서 동작할 수 있다고 밝혔어요.\n\n이 브라우저 도구는 사용자가 로그인한 자신의 탭에서 실행되며, 앱의 MCP 서버와는 별개예요. Lovable은 처음에는 읽기 전용이거나 되돌리기 쉬운 도구부터 제공하고, 삭제, 결제, 전송, 게시 도구는 요청한 경우에만 추가한다고 설명했어요.\n\nchangelog는 항목이 한 페이지에 모여 있어서 항목마다 고정 링크가 없어요. 위 내용은 Oct 13, 2026 항목에 적힌 설명을 기준으로 해요.",
