          "content": "Meshy는 10월 16일 블로그에서 Meshy Edit를 새로운 3D 모델 편집 방식으로 소개했어요. 첫 번째 도구인 local editing은 선택한 부분만 바꾸고 나머지 모델은 그대로 유지한다고 설명해요.\n\n사용 순서는 모델의 한 부분을 선택하고, 텍스트나 참조 이미지로 바꾸고 싶은 내용을 설명한 뒤, 그 부분을 추가하거나 제거하거나 교체하는 방식이에요. Meshy는 모델을 다시 생성하거나 Blender를 열지 않아도 된다고 밝혔고, 이 기능은 모든 가입 사용자에게 바로 제공된다고 해요.\n\nMeshy는 결과가 시도마다 다를 수 있고 한 번으로 끝나지 않을 때도 있다고 덧붙였어요. 작업 시간이 몇 시간에서 몇 분으로 줄어든다는 비교도 Meshy가 직접 내놓은 것이라, 독립적으로 검증된 결과는 아니에요.",
