            "deck": "Change a selected part without regenerating the whole model",
            "summary": "Meshy released local editing, the first tool in Meshy Edit. A user selects a part of a 3D model and describes the change with text or reference images, and only that part is added, removed, or replaced while the rest stays unchanged. The company says it is live now for all registered users.",
            "content": "In a blog post on October 16, Meshy introduced Meshy Edit as a new way to edit a 3D model. It says the first tool, local editing, changes only the part you select and keeps the rest of the model unchanged.\n\nThe flow is to select a part of the model, describe the change with text or reference images, and then add, remove, or replace that part. Meshy says this works without regenerating the model or opening Blender, and that the feature is live now for all registered users.\n\nMeshy added that results vary and sometimes need more than one try. The comparison that the work takes minutes instead of hours is also Meshy's own, so it is not an independently verified result."
