          "content": "Meta는 10월 15일 Muse Spark Open의 가중치를 공개한다고 밝혔어요. 네이티브 멀티모달 모델이고, 전체 파라미터는 816B, 토큰당 활성 파라미터는 42B, 컨텍스트 창은 100만 토큰이에요. 전문가 혼합(MoE) 구조라고 소개했어요.\n\n라이선스는 Muse Model License이고, Meta는 상업적 이용 조건이 제한적이라고 설명했어요. 상업 이용을 검토한다면 라이선스 조항을 먼저 읽어 보는 편이 좋아요.\n\nMeta가 안내한 이용 경로는 다음과 같아요.\n\n- API: Baseten, Fireworks AI, Groq, Modal, Nebius, OpenRouter, Together AI\n- 가중치: Amazon SageMaker AI, Google Cloud Model Garden, Hugging Face, Microsoft Foundry Models\n\nMeta는 이 모델을 지금까지 가장 뛰어난 미국산 오픈 웨이트 모델이라고 소개해요. 이는 Meta가 직접 내세운 평가이고 비교 성능도 Meta가 발표문에서 제시한 결과이므로, 실제로 쓰기 전에 본인의 작업으로 확인해 보는 편이 안전해요.\n\n같은 날 Hugging Face와 Microsoft Foundry도 각자의 글로 이 모델을 소개했어요.",
