            "deck": "An 816B multimodal model under limited commercial terms",
            "summary": "Meta released the weights of Muse Spark Open, a natively multimodal mixture-of-experts model with 816B total parameters, 42B active per token, and a 1M-token context window. It ships under the Muse Model License with limited commercial terms and is available through Hugging Face, major clouds, and several API providers.",
            "content": "Meta said on October 15 that it is releasing the weights of Muse Spark Open. It is a natively multimodal model with 816B total parameters, 42B active parameters per token, and a 1M-token context window. Meta describes it as a mixture-of-experts model.\n\nThe license is the Muse Model License, which Meta says carries limited commercial terms. Anyone considering commercial use should read the license terms first.\n\nMeta lists these ways to use the model.\n\n- API: Baseten, Fireworks AI, Groq, Modal, Nebius, OpenRouter, and Together AI\n- Weights: Amazon SageMaker AI, Google Cloud Model Garden, Hugging Face, and Microsoft Foundry Models\n\nMeta calls the model the most capable US open-weight model to date. That is Meta's own assessment, and the comparison results are the ones Meta presented in its announcement, so it is safer to check them against your own workload before relying on them.\n\nHugging Face and Microsoft Foundry also introduced the model in separate posts on the same day."
