          "content": "Meta가 Facebook에 'Your algorithm'이라는 설정을 내놓는다고 밝혔어요. 피드(Feed)와 릴스(Reels)에서 보고 싶은 주제를 사용자가 직접 추가하고 관리하는 공간이고, 점 세 개 메뉴에서 들어갈 수 있다고 Meta가 설명했어요.\n\n게시물에서 '관심 있음(Interested)' 또는 '관심 없음(Not interested)'을 고르면 Facebook이 후속 질문을 할 수 있어요. Meta는 대규모 언어 모델(LLM)이 랭킹 시스템을 같은 세션 안에서 적응시키는 데 도움을 준다고 밝혔어요.\n\nMeta의 글에는 출시 국가나 일정이 적혀 있지 않아요. 모든 사용자가 같은 시기에 쓸 수 있는지는 확인되지 않았어요.",
