          "content": "Microsoft가 Foundry 블로그에서 Foundry에 호스팅된 GPT-chat-latest의 업데이트를 소개했어요. Microsoft는 이번 업데이트가 대화형 및 에이전트 애플리케이션에 GPT-6 수준의 지능을 가져온다고 밝혔어요. 코딩, 검색, 다국어 상호작용, 개인화, 작업 생성 전반에서 추론이 강해졌다는 설명도 함께 있는데, 이는 Microsoft가 밝힌 내용이에요.\n\n새로 더해진 기능은 시각적이고 상호작용하는 답변을 위한 GenUI 지원과 interleaved-thinking 출력이에요. 개발자는 Foundry의 기존 GPT-chat-latest로 이 개선을 쓸 수 있고, 새 모델을 다시 배포할 필요가 없다고 Microsoft가 밝혔어요.\n\n가격표에는 100만 토큰당 입력 5달러, 캐시된 입력 0.5달러, 출력 30달러가 적혀 있어요. 글에는 정식 출시(GA)인지 프리뷰인지 적혀 있지 않아요.",
