            "content": "Microsoft described an update to GPT-chat-latest, which is hosted in Microsoft Foundry, on the Foundry blog. Microsoft said the update brings GPT-6-level intelligence to conversational and agentic applications. It also described stronger reasoning across coding, search, multilingual interactions, personalization and task creation, which is Microsoft's own claim.\n\nThe update adds GenUI support for visual and interactive answers and interleaved-thinking output. Microsoft said developers can access these improvements through the existing GPT-chat-latest in Foundry and do not need to redeploy a new model.\n\nThe pricing table lists $5 per 1M input tokens, $0.50 per 1M cached input tokens and $30 per 1M output tokens. The post does not state whether the update is generally available or in preview."
