          "content": "Microsoft가 Azure 블로그에서 업계와 협력해 AI 인프라를 키우는 전략을 소개했어요. Open Compute Project를 통한 개방형 협업을 바탕으로 Maia 300, Cobalt 200, 네트워킹, 전력 설계를 차례로 설명한 글이에요.\n\n글에서 Microsoft가 밝힌 내용은 다음과 같아요.\n\n- Maia 300: 선도적인 GPU 기반 시스템보다 와트당 토큰이 40% 많을 것으로 기대한다고 했어요. 96개 가속기 구성에서는 Maia 200보다 랙 단위 토큰 처리량이 최대 7배라고 해요.\n- Cobalt 200: Cobalt 100보다 성능이 50% 넘게 좋아졌다고 밝혔어요.\n- Tessera Integrated HSM: 오픈소스 이니셔티브로 소개했어요.\n\n이 밖에 MRC 네트워킹과 Mt. Diablo 등 네트워킹과 전력 설계 항목도 다뤘어요.\n\n위 수치는 모두 Microsoft가 직접 밝힌 기대치와 주장이에요. 이 글에는 새 모델이나 Foundry 제품 출시 내용이 없어요. Maia의 운영 배포 계획은 Microsoft 공식 블로그의 별도 글에서, Maia 300의 구조는 Azure 블로그의 기술 글에서 각각 다뤘어요.",
