          "content": "Microsoft가 Azure 블로그에 Maia 300 아키텍처를 설명하는 글을 올렸어요. Maia 300은 Microsoft의 3세대 Azure AI 가속기이며, Microsoft는 이를 대규모 언어 모델 추론에 맞춰 만들었다고 밝혔어요.\n\n글에서 소개한 구성은 다음과 같아요.\n\n- 랙: 가속기 4개씩 담은 트레이 24개로 모두 96개 가속기를 167kW 랙 하나에 넣었어요. Microsoft는 Maia 200보다 가속기 밀도가 두 배가 됐다고 설명했어요.\n- 슈퍼팟: 가속기 12,288개로 구성해요.\n\n성능 수치도 나와요. Microsoft는 연산 성능(FLOPs)이 36% 늘고 HBM 대역폭이 2.5배가 된다고 밝혔어요. 이 수치는 모두 Microsoft가 직접 밝힌 사양이며 독립적으로 확인된 결과는 아니에요.\n\n이 글은 Maia 300의 하드웨어 구조를 다룬 기술 글이에요. 모델이나 서비스 출시 소식은 아니에요. 같은 날 Microsoft 공식 블로그에는 Maia 확대 계획을 다룬 글이 따로 올라왔어요.",
