            "content": "Microsoft published a post on the Azure blog explaining the Maia 300 architecture. Maia 300 is Microsoft's third-generation Azure AI accelerator, and Microsoft says it is built for large language model inference.\n\nThe configuration described in the post is:\n\n- Rack: 24 trays of four accelerators each, 96 accelerators in total, within a 167-kW rack. Microsoft says this doubles the accelerator density of Maia 200.\n- Superpod: built from 12,288 accelerators.\n\nThe post also gives performance figures. Microsoft says compute FLOPs rise 36% and HBM bandwidth is 2.5 times higher. All of these are specifications stated by Microsoft and have not been independently confirmed.\n\nThis is a technical post about the hardware design of Maia 300. It is not a model or service launch. On the same day, the official Microsoft blog published a separate post on the plan to expand Maia."
