          "title": "Microsoft, 2027년부터 Azure Maia를 멀티 기가와트 규모로 확대",
          "deck": "Maia를 Microsoft 제품의 주력 추론 시스템으로 삼겠다고 밝혔어요",
          "summary": "Microsoft가 2027년부터 Azure Maia 제품군을 멀티 기가와트 규모로 확대하고 Maia를 Microsoft 제품과 서비스의 주력 추론 시스템으로 삼겠다고 밝혔어요. Maia 200은 이미 Copilot 등 운영 워크로드를 처리 중이고, Maia 300은 2027년부터 운영 배포를 시작해요.",
          "content": "Microsoft가 공식 블로그 글에서 Azure Maia 제품군을 2027년부터 멀티 기가와트 규모 배포로 확대하겠다고 밝혔어요. Microsoft는 Maia를 Microsoft 제품과 서비스의 주력 추론 시스템으로 삼겠다고 설명했어요.\n\n현재 상황과 계획은 다음과 같아요.\n\n- Maia 200: Microsoft Copilot을 포함한 Microsoft의 운영 워크로드를 이미 처리하고 있어요. Microsoft는 올해 말까지 GitHub Copilot과 Microsoft Foundry가 뒤따를 것이라고 밝혔어요.\n- Maia 300: 2027년에 운영 배포를 시작해요.\n\nMaia 300의 성능에 대해서도 Microsoft가 수치를 밝혔어요. 96개 가속기를 모두 갖춘 구성에서 Maia 200보다 랙 단위 토큰 처리량이 최대 7배라고 해요. 또 선도적인 GPU 기반 시스템보다 메가와트당 토큰이 40% 많을 것으로 기대한다고 했어요. 이 40%는 측정 결과가 아니라 Microsoft의 기대치예요.\n\n멀티 기가와트 확대 계획은 Maia 제품군 전체에 대한 것이며 Maia 300만을 가리키지 않아요. 위 수치는 모두 Microsoft가 직접 밝힌 내용이에요. Maia 300의 구조는 Azure 블로그의 별도 기술 글에서 자세히 다뤘어요.",
