          "content": "Microsoft AI는 10월 15일 Lab Notes 글에서 새 모델 MAI-Base-2의 사전 학습을 최근 마쳤다고 밝혔어요. MAI-Base-2는 활성 파라미터 800억 개, 전체 파라미터 2.8조 개의 전문가 혼합(MoE) 파운데이션 모델이에요.\n\n학습은 GB200 GPU 1만 6천 개로 2026년 8월과 9월에 걸쳐 38일 동안 이뤄졌다고 해요. Microsoft AI는 이 모델이 따로 떼어 둔 자체 평가(held-out evaluations)에서 시험한 모든 오픈 웨이트 모델을 앞섰다고 설명해요.\n\n이 성능은 Microsoft AI가 자체 평가로 밝힌 결과예요. 모델은 현재 후속 학습(post-training) 단계에 있고, 아직 공개되지 않았어요.",
