            "deck": "The model is still in post-training and has not been released",
            "summary": "Microsoft AI says it finished pre-training MAI-Base-2, a mixture-of-experts foundation model with 80B active and 2.8T total parameters. Microsoft claims it beats every open-weight model it tested on its own held-out evaluations, but the model is in post-training and has not been released.",
            "content": "In a Lab Notes post on October 15, Microsoft AI said it recently completed pre-training its new model, MAI-Base-2. MAI-Base-2 is a mixture-of-experts foundation model with 80 billion active and 2.8 trillion total parameters.\n\nMicrosoft AI says training ran on 16k GB200 GPUs over 38 days in August and September 2026. It also says the model outperforms every open-weight model it tested on its held-out evaluations.\n\nThat performance claim comes from Microsoft AI's own evaluations. The model is currently undergoing post-training and has not been released."
