          "content": "Mistral AI가 시계열 파운데이션 모델 모음 Timestral을 공개했어요. 회사는 이번 모델이 자사가 처음 내놓는 시계열 파운데이션 모델 모음이라고 밝혔어요. 파라미터 수가 5M, 28M, 123M, 209M인 네 가지 크기로 나왔어요.\n\nMistral은 가장 큰 209M 모델이 이 분야의 주요 공개 벤치마크 세 곳에서 모두 1위를 차지했다고 밝혔어요. 세 벤치마크는 GIFT-Eval, TIME, fev-bench예요. 이 순위는 회사가 직접 밝힌 내용이에요.\n\n제품 페이지의 사양 표에는 라이선스가 Modified MIT로 적혀 있고, Mistral Forge를 통해서도 쓸 수 있다고 안내해요. Hugging Face에는 모델 크기별 저장소도 만들어져 있어요. 기술 보고서는 아직 공개되지 않았고, Mistral은 이후에 내놓겠다고 밝혔어요.",
