            "content": "Mistral AI has released Timestral, a family of time-series foundation models. The company says this is the first such family it has released. It comes in four sizes: 5M, 28M, 123M and 209M parameters.\n\nMistral says the largest 209M model ranks first on all three of the field's main public benchmarks. The three benchmarks are GIFT-Eval, TIME and fev-bench. This ranking is the company's own claim.\n\nThe spec table on the product page lists the license as Modified MIT, and the page says Timestral is also available through Mistral Forge. Repositories for each model size have also been created on Hugging Face. A technical report has not been published yet, and Mistral says it will follow."
