          "content": "네이버는 10월 15일 보도자료에서 팀네이버의 연구 논문 24편이 자연어처리 분야 학회 EMNLP 2026에 채택됐다고 밝혔어요. 논문은 NAVER, NAVER Cloud, NAVER LABS Europe 소속 연구진이 썼고, 한국어 AI, 음성과 비전을 아우르는 멀티모달, LLM의 추론 분석, 에이전트를 다룬다고 해요. 네이버는 EMNLP를 세계 최정상 학회라고 소개했어요.\n\nEMNLP 2026은 10월 24일부터 29일까지 부다페스트에서 열려요. 같은 보도자료에는 ECCV 2026에 논문 23편, ICML 2026에 6편이 채택됐다는 내용도 있어요. 이 숫자들은 모두 네이버가 밝힌 수치예요.\n\n연구 성과를 알리는 발표이고, 새 제품이나 모델이 공개된 것은 아니에요.",
