          "content": "네이버는 2026년 10월 12일 보도자료에서 네이버클라우드가 베트남 대표 IT 기업 FPT와 최근 NAVER 1784에서 양해각서(MOU)를 맺었다고 밝혔어요. 두 회사는 AI 팩토리 사업의 기획, 개발, 운영을 함께 추진하고, 한국, 일본, 베트남 등 아시아태평양 지역에서 GPUaaS(서비스형 GPU) 사업을 넓히기로 했어요.\n\n협력에는 정기적인 엔지니어링 교류가 포함돼요. 공동 과제로는 GPU 인프라 최적화, AI 추론 성능 개선, AI 에이전트의 실제 서비스 환경 구축이 언급됐어요.\n\n이번 발표는 협력 의향을 담은 MOU 단계예요. 보도자료에는 GPU 규모, 투자 금액, 일정이 나오지 않아요.",
