            "content": "In a press release dated October 12, 2026, NAVER said NAVER Cloud recently signed a memorandum of understanding (MOU) with FPT, a leading Vietnamese IT company, at NAVER 1784. The two companies will jointly pursue planning, development and operation of AI factory business, and expand GPUaaS (GPU as a service) in the Asia-Pacific region, including Korea, Japan and Vietnam.\n\nThe cooperation includes regular engineering exchanges. The joint tasks named are GPU infrastructure optimization, improving AI inference performance, and building real service environments for AI agents.\n\nThis announcement is at the MOU stage, which expresses an intent to cooperate. The release gives no GPU counts, investment amounts or dates."
