          "content": "네이버는 2026년 10월 12일 보도자료에서 네이버지도의 길안내 경험을 AI 글래스로 확장한다고 밝혔어요. 구글·삼성, 메타와 협력하는 방식이고, 실시간 음성으로 도보 길안내를 받을 수 있다고 설명했어요. 네이버는 이를 국내 지도 서비스 중 처음이라고 소개했는데, 이는 네이버의 자체 표현이에요.\n\n가장 먼저 만날 수 있는 기기는 메타의 Ray-Ban Meta와 Oakley Meta예요. 구글·삼성이 올해 안에 출시할 예정인 인텔리전트 아이웨어에서도 이용할 수 있다고 해요. 지원 운영체제는 안드로이드가 먼저이고, iOS는 순차적으로 이어진다고 밝혔어요.\n\n보도자료에는 Meta 글래스에서 길안내가 실제로 시작되는 날짜가 적혀 있지 않아요. 이번 발표 전에 메타 쪽에서도 9월 말에 네이버지도와의 협력 소식을 먼저 알린 적이 있어요.",
