            "deck": "It comes first to Ray-Ban Meta and Oakley Meta, NAVER says",
            "summary": "NAVER said Naver Map's real-time voice guidance extends to AI glasses. It can be met first on Ray-Ban Meta and Oakley Meta and also on Google-Samsung eyewear due within the year. NAVER calls itself the first domestic map service to do so, which is its own claim.",
            "content": "In a press release dated October 12, 2026, NAVER said it is extending Naver Map's guidance experience to AI glasses. It works with Google and Samsung and with Meta, and NAVER describes real-time voice walking guidance. NAVER calls Naver Map the first domestic map service to do this, which is NAVER's own wording.\n\nThe first devices where users can try it are Meta's Ray-Ban Meta and Oakley Meta. NAVER says it is also available on Google-Samsung intelligent eyewear scheduled to launch within the year. Android is supported first, and iOS will follow in sequence.\n\nThe release does not give a date on which guidance goes live on Meta glasses. Before this announcement, Meta had also announced the partnership with Naver Map in late September."
