          "title": "NVIDIA·AI4Bharat, 인도어 22개 사전학습 데이터 공개 예고",
          "deck": "합성 번역 방식 약 2.8조 토큰, 생성 파이프라인도 함께 공개 예정",
          "summary": "NVIDIA와 IIT Madras의 AI4Bharat이 인도어 22개를 아우르는 약 2.8조 토큰 규모의 사전학습 데이터 Nemotron-pretraining-Indic-v1을 소개했어요. 데이터는 영어 문서를 번역해 만든 합성 데이터이고 아직 내려받을 수 없어요. 두 기관은 데이터와 생성 파이프라인을 곧 공개할 예정이라고 밝혔어요.",
          "content": "NVIDIA와 IIT Madras의 AI4Bharat이 인도어 사전학습 데이터 Nemotron-pretraining-Indic-v1을 Hugging Face 블로그에 소개했어요. 인도의 22개 언어를 대상으로 하는 약 2.8조 토큰 규모의 말뭉치예요. 글은 이 말뭉치를 만드는 데 쓴 오픈 GPU 가속 데이터 생성 파이프라인과 함께 곧 공개할 예정이라고 밝혔어요.\n\n그림 1의 설명에 따르면 말뭉치는 각 언어의 고유 문자로 쓴 토큰 2,601.0B와 로마자로 옮긴 토큰 224.6B로 이뤄져 있고, 토큰 수는 Gemma-4 토크나이저로 센 값이에요. 말뭉치는 영어 문서를 번역해 만든 합성 데이터이고, 지금은 공개돼 있지 않아요.\n\nNVIDIA는 인도어 지속 사전학습을 거친 뒤 Super VL 모델의 성능이 개선됐다고 밝혔어요. 이 결과는 NVIDIA가 직접 보고한 것이고, 합성 데이터와 자연 데이터를 함께 쓴 결과예요. NVIDIA는 Nemotron 3.5 Super VL 개발자 블로그에서도 약 2.8T 토큰 전체 데이터셋을 공개하겠다고 밝혔어요.",
          "source": "https://huggingface.co/blog/nvidia/scaling-indic-pretraining",
          "officialUrl": "https://huggingface.co/blog/nvidia/scaling-indic-pretraining",
          "verifiedAt": "2026-10-18",
          "slug": "nvidia-ai4bharat-nemotron-indic-pretraining",
