          "en": {
            "title": "NVIDIA and AI4Bharat preview Indic pretraining data for 22 languages",
            "deck": "About 2.8 trillion synthetic translated tokens, with the generation pipeline to follow",
            "summary": "NVIDIA and IIT Madras' AI4Bharat introduced Nemotron-pretraining-Indic-v1, a pretraining corpus of about 2.8 trillion tokens covering 22 Indian languages. The data is synthetic, translated from English documents, and is not yet available to download. The two organizations say the data and its generation pipeline will be released soon.",
            "content": "NVIDIA and AI4Bharat of IIT Madras introduced the Indic pretraining dataset Nemotron-pretraining-Indic-v1 in a Hugging Face blog post. It is a corpus of about 2.8 trillion tokens covering 22 Indian languages. The post says the corpus will be released soon, together with the open, GPU-accelerated data generation pipeline used to create it.\n\nAccording to the Figure 1 caption, the corpus contains 2,601.0 billion native-script tokens and 224.6 billion romanized tokens, counted with the Gemma-4 tokenizer. The corpus is synthetic, translated from English documents, and it is not public yet.\n\nNVIDIA says the Super VL model improved after Indic continued pretraining. This result is reported by NVIDIA itself and combines synthetic and natural data. NVIDIA's Nemotron 3.5 Super VL developer blog also says the full dataset of about 2.8T tokens will be released."
          }
