            "title": "NVIDIA releases Nemotron 3.5 Super VL, an open multimodal model",
            "deck": "A 120B MoE with 12B active parameters, released with checkpoints and training recipes",
            "summary": "NVIDIA released Nemotron 3.5 Super VL, an open multimodal model with a 120B-parameter mixture-of-experts architecture that activates 12B parameters per token. It says the release includes base, post-trained and NVFP4 checkpoints along with training recipes, data and reinforcement-learning environments. A same-day press post also announced two Nemotron 3.5 Bolt edge models.",
            "content": "NVIDIA has released Nemotron 3.5 Super VL, an open multimodal model. NVIDIA presents it as a customizable model for specialized agent workflows. It uses a 120B-parameter mixture-of-experts (MoE) architecture that activates 12B parameters per token. OpenRouter independently describes it as 12B active out of 120B total.\n\nNVIDIA says the release includes base, post-trained and NVFP4-quantized checkpoints, along with training recipes, data and reinforcement-learning environments. The press post says the model is available now on Hugging Face, OpenRouter, the ModelScope community and as NVIDIA NIM.\n\nStatements about speed and accuracy, including up to 5x higher throughput, are NVIDIA's own claims.\n\nThe same-day press post also announced two edge models. NVIDIA says Nemotron 3.5 Bolt 74B-A9B is available now and that Bolt E4B is coming on October 23."
