          "en": {
            "title": "NVIDIA publishes an open midtraining recipe for agentic post-training",
            "deck": "Reported score changes on SWE-bench and DeepSWE for two Nemotron 3.5 models",
            "summary": "NVIDIA authors posted a preprint describing an open midtraining recipe that primes base models for agentic post-training. The stage uses software-engineering data at 256K context and was applied to Nemotron 3.5 Lightning and Super. The SWE-bench and DeepSWE gains are the authors' own measurements.",
            "content": "NVIDIA researchers have posted a paper on arXiv describing an open midtraining recipe that primes base models for agentic post-training. The paper is titled Priming Base Models for Agentic Post-Training: An Open Midtraining Recipe and was submitted on October 15, 2026. It is a preprint that has not been peer reviewed.\n\nIn the abstract, the authors say they show the recipe's effectiveness on two Nemotron models of different sizes. According to the paper, the stage trains on software-engineering data at 256K context.\n\nThe results in the paper are the authors' own measurements.\n\n- Nemotron 3.5 Lightning: with 500B midtraining tokens, the score on SWE-bench Verified rose from 60.7 to 64.5, according to the authors.\n- Nemotron 3.5 Super: with 280B tokens, the score on DeepSWE rose from 11.7 to 15.7, according to the authors.\n\nThe abstract page prints no affiliation, but the full-text HTML lists the affiliation as NVIDIA. The paper has 14 authors and is filed under cs.CL."
          }
