          "deck": "GPU와 AI 워크로드 오케스트레이션을 GitHub에서 쓸 수 있어요",
          "summary": "NVIDIA가 DSX AI Factory 플랫폼의 일부로 Run:ai 플랫폼 전체를 오픈소스로 공개했어요. KAI Scheduler 등 네 구성 요소는 따로 도입할 수 있고, DSX 파트너 8곳이 통합을 진행하고 있어요.",
          "content": "NVIDIA가 10월 13일 NVIDIA Run:ai 플랫폼 전체를 오픈소스 소프트웨어로 제공한다고 발표했어요. NVIDIA는 고객, 개발자, 생태계 파트너가 프로덕션 수준의 AI 워크로드와 GPU 오케스트레이션 기능을 쓸 수 있게 하려는 조치라고 설명했어요. 코드는 GitHub의 dsx-ai-factory 조직 저장소에 있고, README는 Run:ai를 Kubernetes에서 공유 AI 인프라를 관리하는 오픈소스 AI 워크로드 및 GPU 오케스트레이션 플랫폼이라고 소개해요.\n\n공개 범위는 전체 Run:ai 플랫폼과, 독립적으로 도입할 수 있는 네 구성 요소예요.\n\n- KAI Scheduler\n- GPU Fractioning Operator\n- KAI Resource Management\n- Workload Map\n\nNVIDIA는 DSX 생태계 파트너 8곳(Crusoe, Mirantis, Nebius, OpenNebula Systems, Rafay, Saturn Cloud, Spectro Cloud, vCluster)이 이를 통합하고 있다고 밝혔어요. NGC에서 받는 Community Product는 유료 구독이 필요 없지만, 엔터프라이즈 지원은 포함되지 않아요.",
