          "date": "10/14",
          "platform": "Web",
          "title": "Ollama 0.40.4·0.40.5, 결정 모델과 Nemotron 3.5 Super",
          "deck": "터미널에서 결정 모델을 쓰고 Nemotron 3.5 Super를 받을 수 있어요",
          "summary": "Ollama 0.40.4는 ollama run --ask로 예/아니오 질문, 라벨 분류, 기준표 채점을 하는 결정 모델 실행을 넣었어요. 0.40.5는 NVIDIA Nemotron 3.5 Super를 추가했고 결정 모델의 클라우드 이용도 열었어요.",
          "content": "Ollama가 10월 12일과 14일에 0.40.4와 0.40.5를 연이어 내놓았어요. 두 릴리스 모두 결정 모델(decision model)이 중심이에요.\n\n- 0.40.4 (10월 12일): 릴리스 노트에 따르면 결정 모델을 터미널에서 ollama run으로 바로 쓸 수 있어요. 예/아니오 질문, 텍스트의 라벨 분류, 기준표(rubric) 채점을 할 수 있고, ollama run nimble --ask \"Is a refund being requested?\" 명령에 ticket.txt 파일을 입력으로 넘기는 예시가 소개돼 있어요. Apple silicon에서는 결정 모델용 MLX 러너 지원이 들어왔고, llama.cpp는 결정 모델을 기본 지원하는 버전으로 업데이트됐어요.\n- 0.40.5 (10월 14일): NVIDIA Nemotron 3.5 Super가 추가됐어요. 노트는 이 모델을 코딩, 추론, 도구 사용, 문서 이해를 위한 비전-언어 모델이라고 설명해요. 120B 파라미터의 Mamba-2/Transformer 하이브리드 mixture-of-experts 구조이고 토큰당 12B가 활성화되며, 컨텍스트는 최대 1M 토큰이에요. 실행 명령은 ollama run nemotron-3.5-super예요. 노트는 더 작은 형제 모델인 Nemotron 3.5 Bolt가 74B(활성 9B)라고도 적고 있어요. 결정 모델은 Ollama 클라우드(clef:cloud, clef-flash:cloud)에서도 쓸 수 있어요.",
