          "summary": "OpenAI는 ChatGPT의 GPT-6 Astra Pro가 더 빠른 응답과 개선된 플러그인, 도구 사용을 갖췄고, 여러 에이전트가 한 작업의 서로 다른 부분을 병렬로 처리할 수 있게 됐다고 밝혔어요. 각 에이전트의 진행 상황을 따라가고 끝난 작업을 열어 검토할 수 있다고 해요. Chat 탭의 Pro 사용자에게 제공된다고 했어요.",
          "content": "OpenAI는 10월 16일 공식 X 게시물에서 ChatGPT의 GPT-6 Astra Pro가 업그레이드됐다고 알렸어요. 응답이 더 빨라지고 플러그인과 도구를 쓰는 방식이 좋아졌다고 설명했어요.\n\n새 기능은 여러 에이전트가 한 작업의 서로 다른 부분을 병렬로 맡는 거예요. OpenAI에 따르면 사용자는 각 에이전트의 진행 상황을 따라가고, 완료된 작업을 열어 결과를 검토할 수 있어요. 제공 대상은 Chat 탭의 Pro 사용자예요.\n\n게시물에는 속도 개선 수치도, 동시에 쓸 수 있는 에이전트 수의 한도도 나와 있지 않아요. 그래서 이 카드의 성능 설명은 OpenAI의 표현을 그대로 옮긴 거예요. 한국 매체 AI타임스는 '일부 Pro 계정'이라는 표현을 덧붙였지만, OpenAI 게시물은 Pro 사용자에게 제공된다고 적고 있어요.",
          "source": "https://x.com/OpenAI/status/2111192259073094035",
