          "en": {
            "title": "ChatGPT's GPT-6 Astra Pro Adds Multiple Agents Working in Parallel",
            "deck": "OpenAI also cites faster responses and better tool use",
            "summary": "OpenAI says GPT-6 Astra Pro in ChatGPT got an upgrade with faster responses and improved use of plugins and tools, and that multiple agents can now tackle different parts of a task in parallel. You can follow each agent's progress and open completed tasks to review their work. It says this is available to Pro users in the Chat tab.",
            "content": "In an official X post on October 16, OpenAI announced an upgrade to GPT-6 Astra Pro in ChatGPT. It says responses are faster and that the model uses plugins and tools better.\n\nThe new capability is that multiple agents can handle different parts of one task in parallel. According to OpenAI, you can follow each agent's progress and open completed tasks to review their work. It is available to Pro users in the Chat tab.\n\nThe post gives no figures for the speed improvement and no limit on how many agents can run at once, so the performance descriptions here repeat OpenAI's own wording. The Korean outlet AI Times added the wording 'some Pro accounts', while OpenAI's post says it is available to Pro users."
          }
