          "summary": "OpenAI의 ChatGPT 계정은 Chrome 확장에서 ChatGPT가 열린 탭을 활용할 수 있다고 밝혔어요. Chat에서는 여러 탭에서 정보를 모으고, Work에서는 탭을 제어해 메시지 전송, 양식 작성, 파일 다운로드를 할 수 있어요. 모든 ChatGPT 요금제에서 쓸 수 있다고 해요.",
          "content": "ChatGPT 공식 계정은 10월 15일 X 스레드에서 Chrome 사용자를 위한 업데이트를 발표했어요. OpenAI는 컴퓨터 사용(computer use) 기능을 Chrome을 쓰는 누구에게나 제공하겠다고 밝혔고, 그 첫 번째가 Chrome 탭 활용이에요.\n\n- Chat: 열려 있는 여러 탭을 살펴 정보를 모아 줘요.\n- Work: Chrome 탭을 직접 제어해 메시지 보내기, 양식 채우기, 파일 내려받기 같은 일을 해요.\n\n스레드의 이어지는 게시물은 이 기능을 모든 ChatGPT 요금제에서 쓸 수 있다고 밝혔어요. 예시 프롬프트에는 @chrome 멘션이 포함돼 있어요. Chrome 웹 스토어의 ChatGPT 확장 페이지는 개발자를 OpenAI로 표시하고 10월 16일에 업데이트됐다고 적고 있어요.",
