            "deck": "In Chat it gathers info across tabs, and in Work it acts on tabs",
            "summary": "The ChatGPT account at OpenAI says the ChatGPT Chrome extension can now use your open tabs. In Chat it gathers information across tabs, and in Work it can control tabs to send messages, fill out forms or download files. The post says it is available for all ChatGPT plans.",
            "content": "In an X thread on October 15, the official ChatGPT account announced updates for Chrome users. OpenAI says it is bringing computer use to anyone who uses Chrome, and the first feature is using tabs in Chrome.\n\n- Chat: it looks across your open tabs and gathers information.\n- Work: it controls your Chrome tabs to do things such as sending messages, filling out forms and downloading files.\n\nA later post in the thread says the feature is available for all ChatGPT plans. An example prompt in the thread includes an @chrome mention. The ChatGPT page in the Chrome Web Store lists OpenAI as the developer and shows an update date of October 16."
