          "deck": "설정 검색, 리더 키, 데몬 재시작 명령도 추가됐어요",
          "summary": "Codex CLI 0.163.0은 Codex가 응답하는 동안 보낸 후속 메시지로 진행 방향을 바로 바꿀 수 있게 해요. /config 설정 검색, /keymap 리더 키, /daemon 재시작 명령도 새로 들어갔어요.",
          "content": "OpenAI의 Codex 저장소가 10월 15일 CLI 릴리스 0.163.0(태그 rust-v0.163.0)을 공개했어요. 릴리스 노트의 새 기능 목록은 다음과 같아요.\n\n- 응답 중 조정: Codex가 답하는 동안 후속 메시지를 보내면 그 내용으로 바로 방향을 바꿀 수 있어요.\n- 설정 검색: /config를 열면 여러 범주의 설정을 검색하고 지원되는 설정은 바로 바꿀 수 있어요.\n- 리더 키: /keymap에서 리더 키를 지정할 수 있고 기본값은 Ctrl+X예요.\n- 데몬 재시작: /daemon에서 관리되는 백그라운드 서버를 재시작할 수 있어요.\n- 병렬 실행: 서로 독립적인 읽기 전용 도구를 병렬로 실행해요.\n\n전체 변경 목록은 GitHub 릴리스 페이지에서 확인할 수 있어요.",
          "source": "https://github.com/openai/codex/releases/tag/rust-v0.163.0",
          "officialUrl": "https://github.com/openai/codex/releases/tag/rust-v0.163.0",
