          "en": {
            "title": "Codex CLI 0.163.0 Lets You Steer a Response With a Follow-Up Message",
            "deck": "It also adds searchable settings, a keymap leader key and a daemon restart command",
            "summary": "Codex CLI 0.163.0 lets a follow-up message sent while Codex is responding steer it immediately. It also adds a searchable /config panel, a /keymap leader key and a /daemon restart command.",
            "content": "OpenAI's Codex repository published CLI release 0.163.0 (tag rust-v0.163.0) on October 15. The New Features list in the release notes is as follows.\n\n- Steering during a response: sending a follow-up message while Codex is responding steers it immediately.\n- Settings search: opening /config lets you search preferences across categories and change supported settings immediately.\n- Leader key: you can configure a leader key in /keymap, and the default is Ctrl+X.\n- Daemon restart: you can restart a managed background server from /daemon.\n- Parallel tools: independent read-only tools run in parallel.\n\nThe full list of changes is available on the GitHub release page."
          }
