          "content": "OpenAI는 10월 15일 공식 X 계정에서 GPT-Live-1.1을 소개했어요. 게시물은 새 목소리, 더 나은 억양, 그리고 'checking...' 같은 확인 멘트가 줄어든 점을 업데이트로 꼽았어요.\n\n이 업데이트는 ChatGPT의 음성 기능, Codex, dots에 적용되고, 새 목소리는 프랑스어, 독일어, 힌디어, 멕시코 스페인어, 한국어, 일본어로 추가돼요. OpenAI는 이날 모든 사용자에게 순차적으로 제공하기 시작했고 API에는 곧 제공한다고 밝혔어요.\n\n게시물에는 한국어 목소리의 개수와 이름이 나와 있지 않아요. 억양이 얼마나 좋아졌는지 보여 주는 수치도 없어요.",
