          "content": "OpenAI가 10월 13일 스타트업 Higgsfield의 고객 사례 글을 올렸어요. 제목은 'Higgsfield takes AI video from 1 minute to over 10'이고, OpenAI는 요약문에서 Higgsfield가 GPT-6 Astra로 더 긴 영상을, GPT-Image-2.5로 정밀한 화면을, GPT-Live로 음성 영화 제작으로 가는 길을 크리에이터에게 제공한다고 소개했어요.\n\n이 글은 OpenAI가 고객 사례로 소개한 내용이라서 영상이 길어졌다는 설명도 OpenAI와 Higgsfield 쪽 주장에 해당해요. 독립 매체 Blockchain.News는 OpenAI 글에 벤치마크, 가격, 출시 일정이 나와 있지 않고, 음성 영화 제작도 앞으로 가능한 방향으로 설명되어 있다고 짚었어요.\n\n이 카드는 OpenAI 제목과 요약문에 나온 내용만 정리했어요. 세부 내용은 OpenAI 원문에서 확인해 주세요.",
