            "deck": "A customer story on GPT-6 Astra, GPT-Image-2.5 and GPT-Live",
            "summary": "OpenAI published a customer story about the startup Higgsfield. Its title says AI video length grew from 1 minute to over 10, and it presents the work as built on GPT-6 Astra, GPT-Image-2.5 and GPT-Live.",
            "content": "On October 13, OpenAI published a customer story about the startup Higgsfield. The title is 'Higgsfield takes AI video from 1 minute to over 10', and OpenAI's description says Higgsfield brings creators longer videos with GPT-6 Astra, precise visuals with GPT-Image-2.5, and a path to voice filmmaking with GPT-Live.\n\nBecause this is a customer story published by OpenAI, the claim about longer videos reflects what OpenAI and Higgsfield say. The independent outlet Blockchain.News noted that the OpenAI post gives no benchmarks, pricing or rollout details, and that it frames voice filmmaking as a future direction.\n\nThis card covers only what appears in OpenAI's title and description. Please check the original post for details."
