          "summary": "OpenAI가 사무실 한 곳에 정교한 녹음 장치가 숨겨져 있었다고 밝혔어요. 자사 모델로 장치와 출처를 분석해 특정 직원이 설치한 것으로 확인했고 FBI에 사건을 넘겼다고 해요. 모델 가중치, 소스 코드, 고객 데이터에 부적절하게 접근한 징후는 없다고 설명했어요.",
          "content": "OpenAI Newsroom은 10월 13일 X 게시물에서 사무실 한 곳 안에 정교한 녹음 장치가 숨겨져 있었다고 밝혔어요. OpenAI는 자사 모델을 사용해 이 장치가 무엇이고 어디서 왔는지 파악했고, 특정 직원이 며칠 전에 설치한 것으로 확인했다고 설명했어요.\n\nOpenAI는 이 사안을 FBI에 넘겼다고 했어요. 또 해당 직원이 모델 가중치, 소스 코드, 고객 데이터에 부적절하게 접근하거나 빼돌린 징후는 없다고 밝혔고, 그 직원은 해고됐다고 전했어요.\n\n체포와 관련된 내용은 미국 법무부(DOJ)를 인용한 CNBC와 가디언 보도에 담겨 있어요. 위 설명은 OpenAI 게시물의 내용을 옮긴 것이므로, 수사 결과는 법무부와 수사 당국의 발표를 따로 확인해야 해요.",
