            "deck": "It says it used its models to trace the device and referred the matter to the FBI",
            "summary": "OpenAI said a sophisticated recording device was hidden inside one of its offices. It says it used its own models to analyze the device and its origin, identified a specific employee as the person who planted it, and referred the matter to the FBI. OpenAI also says it has no indication that model weights, source code or customer data were accessed.",
            "content": "In an October 13 post on X, OpenAI Newsroom said a sophisticated recording device had been hidden inside one of its offices. OpenAI says it used its models to understand what the device was and where it came from, and identified that a specific employee had planted it a few days earlier.\n\nOpenAI said it referred the matter to the FBI. It also said it has no indication that the individual inappropriately accessed or exfiltrated model weights, source code or customer data, and that the employee was terminated.\n\nDetails about the arrest come from CNBC and The Guardian, which cite the U.S. Department of Justice. The account above reflects OpenAI's post, so the investigation's findings should be checked against statements from the Department of Justice and investigators."
