          "title": "OpenMOSS, 레이아웃 제어 이미지 모델 MOSS-Image-Base 공개",
          "deck": "5B 규모 모델의 코드와 Apache-2.0 가중치가 공개됐어요",
          "summary": "OpenMOSS 팀이 5B 규모의 텍스트-이미지 생성 모델 MOSS-Image-Base를 공개했어요. 물체와 글자, 위치를 JSON으로 지정하는 레이아웃 프롬프트를 지원하고, 코드와 Apache-2.0 가중치가 함께 공개됐어요.",
          "content": "OpenMOSS 팀은 프로젝트 페이지 뉴스에 10월 16일자로 MOSS-Image-Base를 소개하며 코드와 모델 가중치를 함께 공개했다고 적었어요. 모델 가중치의 라이선스는 Apache-2.0이에요.\n\nMOSS-Image는 텍스트-이미지 생성 모델 계열이고, 이번에 공개한 Base는 그 기반 모델이에요. 프로젝트 페이지에 따르면 5B 규모의 작은 백본을 쓰고 최대 4K 토큰 길이의 프롬프트를 받아요. 자연어 프롬프트와 태그 나열뿐 아니라, JSON으로 글자의 위치와 물체 배치를 지정하는 레이아웃 제어를 기본 기능으로 지원해요. 팀은 글자 렌더링이 강점이라고 설명하지만, 이 품질 평가는 팀의 주장이에요.\n\n기술 보고서는 10월 16일 arXiv에 제출됐어요. 초록은 5B 단일 스트림 디퓨전 트랜스포머(DiT)를 처음부터 사전 학습했다고 설명해요. 초록에 실린 벤치마크 결과는 저자들이 직접 밝힌 것이에요. SFT 모델도 별도로 공개돼 있어요.",
