            "deck": "Code and Apache-2.0 weights for the 5B model are public",
            "summary": "The OpenMOSS team released MOSS-Image-Base, a 5B text-to-image model. It supports JSON layout prompts that specify objects, rendered text and positions, and the code and Apache-2.0 weights are public.",
            "content": "In the news section of its project page, the OpenMOSS team introduced MOSS-Image-Base on October 16, with code and model weights available. The model weights are licensed under Apache-2.0.\n\nMOSS-Image is a family of text-to-image models, and the Base model released now is its base model. According to the project page, it uses a compact 5B backbone and accepts prompts of up to 4K tokens. Besides natural-language prompts and tag sequences, it natively supports layout control, in which JSON specifies where text goes and how objects are arranged. The team describes its text rendering as strong, but that quality assessment is the team's own claim.\n\nA technical report was submitted to arXiv on October 16. Its abstract says a 5B single-stream diffusion transformer (DiT) was pretrained from scratch. The benchmark results in the abstract are the authors' own. A companion SFT model is also published separately."
