          "content": "Perplexity가 SPACE를 오픈소스로 공개했어요. SPACE는 Perplexity의 Computer 세션을 지원하는 샌드박스 플랫폼이에요. 회사는 개발자들이 더 안전한 에이전트 시스템을 만들 수 있는 기반을 주려고 공개한다고 밝혔어요.\n\nPerplexity에 따르면 SPACE는 7월부터 모든 Computer 세션을 지원해 왔어요. 샌드박스 생성 속도는 이전 공급사를 쓸 때보다 3~5배 빨랐다고 하는데, 이는 회사가 자체 비교한 결과예요.\n\n보안 평가도 함께 밝혔어요. 회사는 108번의 시도 중 가상 머신에서 호스트로 빠져나간 경우는 없었지만, 일부 시도는 네트워크 제한을 우회하는 방법을 찾았고 그 약점은 고쳤다고 설명했어요.\n\n블로그 글에는 라이선스가 적혀 있지 않아요. GitHub 저장소 페이지에는 Apache-2.0 라이선스가 표시돼요.",
