          "content": "Reflection AI가 Beam의 모델 가중치를 Hugging Face에 공개했어요. 라이선스는 Apache 2.0이에요. Reflection AI는 Beam을 자사의 첫 오픈 웨이트 모델이라고 소개하며, 고급 코딩과 추론, 오래 이어지는 에이전트 작업을 위해 만들었다고 밝혔어요.\n\n회사 설명에 따르면 Beam은 전체 파라미터가 501B이고 그중 23B가 활성화되는 희소 MoE(Mixture-of-Experts) 모델이에요. 가중치는 BF16, FP8, NVFP4 형식으로 제공돼요. Hugging Face가 올린 글은 컨텍스트 윈도우가 100만 토큰이라고 밝혔어요. Reflection AI는 출시 시점에 파트너와 통합이 40곳이 넘는다고 밝혔어요.\n\nHugging Face와 Transformers도 같은 날 지원을 내놨어요. Hugging Face 블로그에 Beam을 소개하는 글이 올라왔고, Transformers v5.20.1 릴리스에 Beam이 추가됐어요.\n\nReflection AI는 이에 앞서 10월 5일에 Beam의 501B 오픈 웨이트 모델을 처음 소개했어요. 이번 글은 그 모델의 가중치를 Hugging Face에 공개했다는 소식이에요. 모델의 성능과 효율에 대한 설명은 모두 Reflection AI가 직접 밝힌 내용이에요.",
