            "content": "Reflection AI has released the weights of Beam on Hugging Face under an Apache 2.0 license. Reflection AI calls Beam its first open-weight model and says it was built for advanced coding, reasoning and long-horizon agentic workloads.\n\nAccording to the company, Beam is a sparse mixture-of-experts model with 501B total parameters, 23B of them active. The weights are provided in BF16, FP8 and NVFP4. A Hugging Face post states a context window of 1 million tokens. Reflection AI says it had more than 40 partners and integrations at launch.\n\nHugging Face and Transformers shipped support on the same day. A Hugging Face blog post introduces Beam, and the Transformers v5.20.1 release adds Beam.\n\nReflection AI first introduced the 501B open-weight Beam on October 5. This announcement is about the release of the model's weights on Hugging Face. All descriptions of the model's performance and efficiency are Reflection AI's own statements."
