          "title": "상하이 AI 연구소, Intern-S2로 3차원 Ghys 추측 증명 발표",
          "deck": "Lean 형식 검증을 밝혔지만 동료 심사는 거치지 않았어요",
          "summary": "Shanghai AI Laboratory가 자체 과학 모델 Intern-S2와 수학자들이 협력해 3차원 Ghys 추측을 증명했다고 발표했어요. 베이징대 연구팀이 이 증명을 Lean으로 형식 검증했다고 밝혔지만, 증명은 아직 동료 심사를 거치지 않은 사전 공개 논문 단계예요.",
          "content": "Shanghai AI Laboratory는 10월 15일 자체 소식 페이지에서 수학계를 30여 년 괴롭혀 온 세계적 난제인 3차원 Ghys 추측이 풀렸다고 발표했어요. 연구소에 따르면 한 교수가 이끄는 연구팀이 연구소의 Intern-S2(书生-S2) 모델과 인간 수학자의 협업으로 이 추측을 증명했어요.\n\n연구소는 베이징대 연구팀이 증명의 주요 정리 네 개를 모두 Lean으로 형식 검증했다고 밝혔어요. 검증에는 약 5일이 걸렸고, 에이전트를 최대 100개까지 동원했으며, Lean 코드는 약 55만 줄에 이른다고 해요. 연구소가 소개한 형식화 저장소는 GitHub에 공개돼 있어요.\n\n관련 논문은 arXiv에 Codimension-one holomorphic Anosov diffeomorphisms라는 제목으로 올라와 있어요. 초록은 여차원 1인 경우를 증명했고 특히 복소 3차원이 여기에 해당한다고 설명해요. 논문은 단독 저자로 등록돼 있어요. 첫 버전은 9월 29일에 올라왔고, 10월 13일의 v3 코멘트에 AI 사용 선언과 증명 형식화에 관한 설명이 추가됐어요.\n\n중국 대형 모델이 처음으로 세계적 난제를 풀었다는 표현은 연구소의 주장이에요. 이번 증명은 사전 공개 논문 단계라 동료 심사를 거치지 않았고, 형식 검증 결과도 연구소가 밝힌 내용이에요. 중국 국영 매체 CGTN도 같은 날 이 발표를 보도했어요.",
