          "content": "Simons Foundation은 10월 15일 수학자들이 AI 시대를 헤쳐 나가도록 돕는 1,500만 달러 규모의 사업을 시작한다고 발표했어요. 재단은 파트너십에 따라 재단, Anthropic, OpenAI가 합쳐서 1,500만 달러의 자금과 자원을 투입한다고 밝혔어요. 이 금액은 재단 단독 지원금이 아니라 세 곳의 합산액이에요.\n\n자금의 운용은 재단이 맡아요. 재단은 공개 모집을 포함한 방식으로 지원금을 배정하고, 지원 대상은 워크숍과 여러 사업이에요. 사업의 목적은 AI의 도움을 받은 수학 연구 결과를 평가하고, 연구자들이 AI 도구를 익히며, AI 사용에 관한 공동의 기준을 함께 만드는 거예요. Anthropic과 OpenAI는 AI 도구와 컴퓨팅 자원을 제공해요.\n\n재단 측은 지금이 수학계가 함께 모여야 할 때라고 밝혔어요.",
