          "content": "SpaceXAI가 10월 12일 The X Subscription을 발표했어요. 회사는 공지에서 \"Today we’re introducing The X Subscription, which brings together Grok, Grok Bot, Cursor, and X Premium in one plan\"이라고 소개했어요. Grok, Grok Bot, Cursor, X Premium을 하나의 요금제로 묶은 구독이라는 설명이에요.\n\n공지의 요금표에 실린 다섯 단계는 아래와 같아요.\n\n- Free: 0달러\n- Plus: 월 8달러\n- Premium: 월 30달러\n- Super: 월 100달러\n- Ultra: 월 200달러\n\n단계가 올라갈수록 월 요금이 높아지고, 회사는 단계별 사용량 배율도 함께 제시했어요. 요금표에는 이전에는 합산 월 90달러였다는 문구도 실려 있어요. 사용량 배율과 이 가격 비교는 모두 SpaceXAI가 직접 내놓은 비교예요.\n\n제공 시점에 대해서는 앞으로 며칠에 걸쳐 전 세계 모든 사용자에게 열겠다고 밝혔어요. 공지 시점에는 모든 사용자에게 열린 상태가 아니에요. 같은 날 Cursor 포럼에도 이 구독을 소개하는 글이 올라왔어요.",
