          "summary": "StepFun이 600B 파라미터, 활성 27B 규모의 희소 MoE 모델 Step 5 Preview의 가중치를 StepFun Model License 1.0으로 허깅페이스에 공개했어요. 모델과 API는 9월 20일에 먼저 발표됐고, 이번 소식은 가중치 공개예요.",
          "content": "StepFun은 Step 5 Preview의 모델 가중치를 허깅페이스(Hugging Face)에 공개했어요. 모델 카드는 이 모델을 에이전트 작업용 StepFun의 플래그십 모델이라고 소개해요. 구조는 희소 전문가 혼합(sparse Mixture-of-Experts, MoE)이고 전체 파라미터는 600B, 활성 파라미터는 27B이며 최대 100만 토큰 컨텍스트를 지원한다고 적혀 있어요.\n\n라이선스는 StepFun Model License 1.0이에요. 모델 카드는 이를 Apache-2.0 방식을 바탕으로 하되 출처 표기와 상업 라이선스 조건이 더해진 라이선스라고 설명해요. 저장소는 공개 상태이고 접근 제한이 없으며 FP8 safetensors 파일이 들어 있어요.\n\n모델과 API는 9월 20일에 먼저 발표됐어요. StepFun은 당시 글에서 Step 5 Preview를 전면 개방한다고 밝히면서 10월 15일에 모델 가중치를 공개하겠다고 예고했어요. 모델 카드에는 공개 날짜가 적혀 있지 않지만, 허깅페이스와 GitHub의 갱신 기록이 10월 15일 무렵이라 이 날짜로 정리했어요. 이번 소식은 9월의 발표가 아니라 이 가중치 공개를 다뤄요.\n\n성능 비교 수치는 StepFun이 직접 제시한 것이고 검증하지 않았기 때문에 여기에는 싣지 않았어요.",
