            "summary": "StepFun released the weights of Step 5 Preview, a 600B-parameter sparse MoE model with 27B active parameters and a 1M-token context, on Hugging Face under StepFun Model License 1.0. The model and its API were announced on September 20, and this news is the open-weights release.",
            "content": "StepFun released the model weights of Step 5 Preview on Hugging Face. The model card calls it StepFun's flagship model for agentic work. It is a sparse Mixture-of-Experts (MoE) model with 600B total parameters and 27B active parameters, and the card says it supports up to 1 million tokens of context.\n\nThe license is StepFun Model License 1.0. The model card describes it as an Apache-2.0-style license with additional attribution and commercial-license conditions. The repository is public and not gated, and it contains FP8 safetensors files.\n\nThe model and its API were announced earlier, on September 20. In that post, StepFun said Step 5 Preview was fully open from that day and announced that it would release the model weights on October 15. The model card prints no release date, but the update records on Hugging Face and GitHub fall around October 15, so this date is used. This news covers the weights release, not the September announcement.\n\nBenchmark and cost comparisons are StepFun's own claims and were not verified, so they are not included here."
