          "summary": "Tencent Hunyuan 연구진이 HYDRA-1.5B, HYDRA-7B와 두 가지 HYDRA-TOK 토크나이저의 가중치, 그리고 추론·학습·평가 코드를 2026년 10월에 공개했어요. HYDRA는 Qwen2.5 백본 위에서 이미지 이해와 생성에 토크나이저 하나를 쓰는 통합 멀티모달 모델이에요.",
          "content": "Tencent Hunyuan의 HYDRA GitHub 저장소 README 소식란에 2026년 10월 항목 두 줄이 올라왔어요. 하나는 Hugging Face에 HYDRA-1.5B, HYDRA-7B와 두 HYDRA-TOK 토크나이저의 모델 가중치를 공개했다는 내용이고, 다른 하나는 추론, 학습, 평가 코드를 공개했다는 내용이에요. Hugging Face 파일 목록에서도 1.5B 모델, 7B 모델, 토크나이저 두 종류가 확인돼요.\n\nHYDRA는 Qwen2.5 백본 위에서 이미지 이해와 생성 모두에 표현 조화(representation-harmonized) 토크나이저 하나를 쓰는 통합 멀티모달 모델이에요. 논문은 2026년 3월에 arXiv에 처음 올라왔고, 이번 소식은 논문이 아니라 가중치와 코드 공개예요. README가 성능 표를 논문에 맡기고 있어서 이 카드에는 벤치마크 수치를 싣지 않았어요.\n\n날짜 근거는 다음과 같아요. README에는 2026년 10월로만 적혀 있고, 10월 14일은 저장소 기록에서 가져온 날짜예요. 코드는 10월 14일에 올라왔고, 가중치 저장소의 첫 커밋은 10월 13일이에요. 가중치 저장소는 Tencent 조직 계정이 아니라 첫 저자 개인 계정 아래에 있어요.",
