            "deck": "1.5B and 7B models, tokenizers, and inference, training and evaluation code are out",
            "summary": "Tencent Hunyuan researchers released weights for HYDRA-1.5B, HYDRA-7B and two HYDRA-TOK tokenizers, plus inference, training and evaluation code, in October 2026. HYDRA is a unified multimodal model built on Qwen2.5 backbones that uses one representation-harmonized tokenizer for image understanding and generation.",
            "content": "The README news section of the Tencent Hunyuan HYDRA GitHub repository carries two entries dated October 2026. One says model weights for HYDRA-1.5B, HYDRA-7B and both HYDRA-TOK tokenizers were released on Hugging Face. The other says inference, training and evaluation code was released. The Hugging Face file listing also shows a 1.5B model, a 7B model and two tokenizers.\n\nHYDRA is a unified multimodal model built on Qwen2.5 backbones that uses one representation-harmonized tokenizer for both image understanding and generation. The paper first appeared on arXiv in March 2026, and this news is about the weights and code, not the paper. The README points to the paper for its benchmark tables, so this card carries no benchmark numbers.\n\nThe date rests on the following. The README says only October 2026, and October 14 is taken from repository records. The code was uploaded on October 14, and the first commit in the weights repository is dated October 13. The weights repository sits under the first author's personal account rather than a Tencent organization account."
