          "content": "TypeSafe AI는 14일 블로그에서 개선된 Jev 1.14.0과 함께, 'dreamers'를 위한 실험 기능을 공개한다고 밝혔어요. 글의 요약에는 이미지, 새로운 타입, 더 긴 컨텍스트가 실험 기능으로 적혀 있어요.\n\nJev 1.14.0은 jev-preview로 먼저 제공되고, jev-latest는 일주일 뒤 1.14.0으로 옮겨 간다고 회사는 설명했어요. 회사는 이번 버전에서 전반적으로 작은 개선이 있고 특히 다국어 지원이 나아졌다고 소개했어요.\n\n실험 기능은 API 헤더의 'danger zone' 플래그 뒤에 두어 원하는 사용자만 켜도록 했어요. 이미지 입력, 경계 상자(bounding box)를 다루는 새 'box' 타입(1.14.0에서만 제공), 더 긴 컨텍스트가 여기에 해당해요. 개선 내용은 모두 TypeSafe AI가 밝힌 설명이에요.",
