          "date": "10/18",
          "platform": "Web",
          "title": "vLLM v0.32.0, systemone 엔드포인트와 NVFP4 KV 캐시 추가",
          "deck": "커밋 814개, 보안 수정 세 건과 Python 3.10 지원 중단 포함",
          "summary": "vLLM v0.32.0은 363명의 기여자가 만든 커밋 814개를 담은 릴리스예요. 구조화된 상태를 바탕으로 질문에 답하는 POST /v1/systemone 엔드포인트가 기본으로 제공되고, hf 도구와 reasoning parser, 더 많은 GPU에서 쓰는 NVFP4 KV 캐시가 추가됐어요. 보안 수정 세 건이 들어갔고 Python 3.10 지원은 중단됐어요.",
          "content": "vLLM이 v0.32.0을 내놨어요. 릴리스 노트에 따르면 363명의 기여자(신규 121명)가 만든 커밋 814개가 담겼어요.\n\n주요 변경은 다음과 같아요.\n\n- 새 엔드포인트 POST /v1/systemone이 추가됐어요. 구조화된 상태를 바탕으로 choice, noul, score 유형의 질문에 답하고, 기본으로 제공돼요 (#59299).\n- hf 도구와 reasoning parser가 추가됐어요.\n- 더 많은 GPU에서 NVFP4 KV 캐시를 쓸 수 있어요.\n- 보안 수정이 세 건 들어갔어요. 권고 번호는 GHSA-4hhp-h66f-j5j7, GHSA-q97c-p368-75c4, GHSA-frvg-qw88-hww9예요.\n\n호환성이 깨지는 변경도 있어요. 대표적으로 Python 3.10 지원이 중단됐어요. 릴리스 노트에 실린 성능 수치는 각 변경 사항의 PR에서 자체 벤치마크로 측정한 값을 옮긴 것이에요. 업그레이드를 계획한다면 릴리스 노트의 호환성 변경 항목을 먼저 확인하는 것이 좋아요.",
          "source": "https://github.com/vllm-project/vllm/releases/tag/v0.32.0",
