          "deck": "Voice Agent API 가격은 분당 0.08달러로 2.0과 같아요",
          "summary": "xAI가 10월 14일 음성 대 음성 모델 Grok Voice 3.0을 발표했어요. Voice Agent API에서 분당 0.08달러(시간당 4.80달러)에 쓸 수 있고, 가격은 Grok Voice 2.0과 같아요. xAI는 Artificial Analysis Speech-to-Speech Index 1위(86.9점)라고 밝혔고, 해당 페이지에서도 같은 점수가 확인돼요.",
          "content": "xAI가 10월 14일 음성 대 음성(speech-to-speech) 모델 Grok Voice 3.0을 발표했어요. xAI는 이 모델을 세계에서 가장 지능적인 음성 대 음성 모델이라고 소개했는데, 이 표현은 회사의 주장이에요. 고객 지원 통화 해결에서 새 기록을 세웠고, 지연 시간이 1초 미만으로 같은 등급에서 가장 낫고, 다른 최상위 모델보다 저렴하다는 설명도 덧붙였어요.\n\nGrok Voice 3.0은 발표 당일부터 Voice Agent API에서 쓸 수 있어요. 가격은 분당 0.08달러(시간당 4.80달러)로 Grok Voice 2.0과 같아요. grok-voice-latest를 쓰던 에이전트는 이미 자동으로 3.0으로 전환됐다고 xAI는 밝혔어요.\n\n외부 지표로는 xAI가 Artificial Analysis를 인용했어요. xAI에 따르면 Grok Voice 3.0은 Speech-to-Speech Index에서 86.9점으로 1위이고, Full Duplex Bench에서 97%를 기록했어요. Artificial Analysis의 speech-to-speech 페이지 차트 데이터에서도 Grok Voice 3.0이 86.9점으로 가장 앞에 있고 97.0%가 확인돼요. 다만 가장 지능적이라는 표현과 고객 지원 통화, 지연 시간, 가격 비교에 관한 주장은 xAI가 직접 밝힌 내용이에요.",
