            "deck": "Voice Agent API pricing is 0.08 US dollars per minute, the same as 2.0",
            "summary": "xAI announced Grok Voice 3.0, a speech-to-speech model available through its Voice Agent API at 0.08 US dollars per minute, the same price as Grok Voice 2.0, with the grok-voice-latest alias moved to it automatically. xAI claims the top Artificial Analysis Speech-to-Speech Index score of 86.9, which the Artificial Analysis page also shows.",
            "content": "On October 14, xAI announced Grok Voice 3.0, a speech-to-speech model. xAI calls it the world's most intelligent speech-to-speech model, which is the company's own claim. It adds that the model sets a new record for resolving customer support calls, has class-leading latency of under one second, and costs less than other frontier models.\n\nGrok Voice 3.0 is available from the day of the announcement in the Voice Agent API. The price is 0.08 US dollars per minute (4.80 US dollars per hour), the same as Grok Voice 2.0. xAI says agents using grok-voice-latest have already been switched over automatically.\n\nFor outside evidence, xAI cites Artificial Analysis. According to xAI, Grok Voice 3.0 ranks first on the Speech-to-Speech Index with a score of 86.9 and scores 97% on Full Duplex Bench. The chart data on the Artificial Analysis speech-to-speech page also shows Grok Voice 3.0 first with 86.9 and 97.0%. The most-intelligent label and the claims about support-call resolution, latency and price comparison are xAI's own statements."
