          "content": "InfiniSplat v2는 Zhejiang University의 ZJU3DV 연구진과 협력 연구자들이 2026년 10월 14일 arXiv에 제출한 논문이에요. 아직 동료 심사를 거치지 않은 프리프린트예요.\n\n논문 설명에 따르면 InfiniSplat v2는 임의의 시점에서 장면을 복원하는 피드포워드 3D 가우시안 스플래팅(3DGS) 모델이에요. 저자들은 가우시안 속성 학습의 한계를 분석하고, 구조와 학습 방식을 바꿔 렌더링 품질을 높였다고 밝혔어요.\n\n저자들은 포즈를 조건으로 주는 설정에서 6개 데이터셋 전반의 평균 LPIPS가 25.8%, DISTS가 32.9% 줄었다고 보고했어요. 비교 대상은 저자들이 평가한 가장 강한 기준 모델이에요. 이 수치는 저자들이 직접 보고한 값이에요.",
