            "summary": "Researchers including Zhejiang University's ZJU3DV group submitted the InfiniSplat v2 paper to arXiv on October 14. It is a feed-forward 3D Gaussian splatting model that reconstructs scenes from arbitrary views, and the authors report mean LPIPS and DISTS lower by 25.8% and 32.9% in the pose-conditioned setting.",
            "content": "InfiniSplat v2 is a paper that the ZJU3DV group at Zhejiang University and collaborators submitted to arXiv on October 14, 2026. It is a preprint that has not been peer reviewed.\n\nAccording to the paper, InfiniSplat v2 is a feed-forward 3D Gaussian splatting (3DGS) model that reconstructs scenes from arbitrary views. The authors say they analyzed limitations in Gaussian attribute learning and improved rendering quality through architectural and training changes.\n\nIn the pose-conditioned setting, the authors report that mean LPIPS and DISTS decrease by 25.8% and 32.9% across six datasets, compared with the strongest baselines they evaluated. These figures are the authors' own reported values."
