          "content": "과학기술정보통신부는 2026년 10월 13일(화) 보도자료에서, 국가 데이터 연계와 AI 학습·활용을 촉진하기 위한 AI기본법 개정안과 데이터산업법 개정안이 국무회의를 통과했다고 밝혔어요.\n\nAI기본법 개정안은 정부 사업으로 구축한 AI 학습데이터를 AI 허브에 연계해 제공하도록 의무화해요. 영업비밀, 개인정보, 저작권 문제가 있는 경우에는 예외를 둬요.\n\n데이터산업법 개정안은 과학기술정보통신부 장관이 공공기관과 민간 기업에 데이터 출처 정보를 One-Window 플랫폼에 연계해 달라고 요청할 수 있게 해요.\n\n두 개정안은 국무회의를 통과한 단계이고, 과학기술정보통신부는 하위 법령을 마련할 예정이라고 밝혔어요. 시행 시기는 이 보도자료 본문에 나와 있지 않아요.",
