            "deck": "The amendments tie AI training data from government projects to the AI Hub",
            "summary": "The Ministry of Science and ICT said on October 13 that amendments to the AI Basic Act and the Data Industry Act passed the Cabinet Council. The AI Basic Act amendment obliges linking and providing AI training data built through government projects to the AI Hub, and the Data Industry Act amendment lets the minister ask public bodies and private firms to link data-source information. The ministry will prepare subordinate rules.",
            "content": "In a press release dated Tuesday, October 13, 2026, the Ministry of Science and ICT said that amendments to the AI Basic Act and the Data Industry Act, aimed at promoting national data linkage and the use of data for AI training, passed the Cabinet Council.\n\nThe AI Basic Act amendment obliges linking and providing AI training data built through government projects to the AI Hub. Exceptions apply where trade secrets, personal data or copyright are involved.\n\nThe Data Industry Act amendment lets the minister of Science and ICT ask public bodies and private firms to link data-source information to the One-Window platform.\n\nBoth amendments have passed the Cabinet Council, and the ministry said it will prepare subordinate rules. The release body does not state when the amendments take effect."
