          "content": "과학기술정보통신부와 기후에너지환경부는 2026년 10월 12일 보도자료를 내고, 10월 13일(화)부터 서울 은평구 주민을 대상으로 AI 폐기물 처리 지원 모바일 앱 '내 손안의 AI 폐기물 처리 도우미, 가져가'의 실증을 시작한다고 밝혔어요. 이 보도자료는 정책브리핑에 기후에너지환경부 자료를 다시 실은 글로 올라와 있어요.\n\n사용자가 폐기물을 사진으로 찍으면 앱이 품목을 자동으로 인식해 분류해요. 위치 정보(GPS)를 지역별 배출 규정과 연결해서 해당 지역의 분리배출 방법과 대형폐기물 수수료 안내를 보여줘요. 배출 신청과 결제도 앱 안에서 한 번에 처리하도록 지원해요.\n\n은평구 주민은 10월 13일부터 Play 스토어와 App Store에서 앱을 내려받을 수 있어요.\n\n이번 소식은 정식 출시가 아니라 특정 지역에서 하는 실증이에요. 이번 보도자료에서 확인된 대상 지역은 은평구예요.",
