          "summary": "한 개인 개발자가 실제 Warcraft III를 Wine에서 플레이하는 강화학습 에이전트를 블로그와 오픈소스 코드로 공개했어요. 3주 만에 가장 어려운 내장 AI를 상대로 약 89% 승률을 냈다고 저자가 보고했어요.",
          "content": "개인 개발자가 Warcraft III의 내장 AI를 상대로 한 자기 대전(self-play) 강화학습 결과를 블로그에 올리고 코드를 GitHub에 공개했어요. 개인 개발자의 프로젝트이며 회사의 공식 제품이나 연구가 아니에요.\n\n저자는 실제 Warcraft III를 Wine에서 실행해 플레이하는 에이전트가 3주 만에 쉬운 AI에게 지던 수준에서 가장 어려운 난이도인 insane AI를 상대로 열 판 중 아홉 판 가까이 이기는 수준까지 올라왔다고 적었어요. 글의 통계에는 89% 승률이, GitHub README에는 약 85~89% 승률이 적혀 있어요. 학습은 데스크톱 한 대에서 했다고 해요.\n\n저자는 10월 18일 추가한 업데이트에서 insane 난이도의 내장 AI가 일반 플레이어보다 금과 목재를 두 배 빠르게 모은다고 덧붙였어요. 이 승률은 내장 AI가 자원 수급에서 이점을 받는 조건에서의 결과예요. 모든 결과는 저자가 직접 보고한 수치이고 독립적으로 평가되지 않았어요.\n\n코드는 MIT 라이선스로 공개돼 있고, 저장소는 9월 23일에 만들어졌어요. 글의 게시일은 블로그 RSS 기준 10월 18일이에요.",
