          "content": "trustbut은 개인 개발자가 GitHub에 올린 오픈소스 프로젝트이며 회사가 내놓은 공식 제품이 아니에요. README는 이 도구를 AI 코딩 에이전트를 위한 'Trust, but verify'라고 소개해요. 에이전트가 끝났다고 말하고 테스트도 통과했을 때, 정말 변경이 증명되는지 묻는 도구예요.\n\nREADME 설명에 따르면 trustbut은 깨끗한 체크아웃에서 테스트를 다시 실행하고, 새로 만들었거나 바뀐 테스트를 변경 이전 코드에 돌려 그 테스트가 거기서 실패하는지 확인해요. 건너뛴 테스트, 제거된 assertion, 무시 처리된 타입 검사도 표시해요. 그런 다음 PASS, WARN, FAIL 중 하나로 판정해요.\n\n저장소 설명은 LLM도 서버도 쓰지 않는다고 밝히고, 라이선스는 Apache-2.0이에요. GitHub 릴리스 기록에서 처음 공개된 릴리스는 10월 13일의 v0.3.0이고, 10월 17일의 v0.7.0까지 올라와 있어요.",
