          "title": "아이오와 등 여러 주 법무장관, OpenAI 상대 소송 발표",
          "deck": "ChatGPT 안전성을 두고 부모를 속였다는 주 정부의 주장",
          "summary": "아이오와 법무장관이 ChatGPT 안전성을 두고 부모와 주민을 속였다며 OpenAI를 상대로 한 소송을 발표했어요. 아칸소, 애리조나, 아이다호, 네브래스카 법무장관실도 같은 날 각자의 소송을 설명하는 보도자료를 냈어요. 모두 주 정부의 주장이며 법원의 판단은 아니에요.",
          "content": "아이오와 법무장관은 10월 14일 기자회견에서 OpenAI가 아이오와 아이들에게 해를 끼치고 부모를 속였으며 아이오와 소비자 사기법을 위반했다며 소송을 제기한다고 밝혔어요. 아이오와 소장의 표지에는 폴크 카운티 아이오와 지방법원이 적혀 있어요.\n\n## 다른 주 법무장관실도 같은 날 소송을 알렸어요\n\n아이오와 법무장관실 페이지는 아칸소, 애리조나, 아이다호, 몬태나도 각자의 주 법원에서 OpenAI를 상대로 소송을 냈다고 적었고, 캔자스, 네브래스카, 웨스트버지니아 법무장관이 기자회견에 함께했다고 밝혔어요. 아칸소, 애리조나, 아이다호, 네브래스카 법무장관실은 각자 보도자료를 냈어요. 애리조나는 메리코파 카운티 Superior Court에 제기했다고 적었고, 아이다호는 에이다 카운티의 제4사법지구 법원이라고 적었어요.\n\n아칸소 법무장관실 보도자료는 같은 날 아이오와, 캔자스, 네브래스카, 웨스트버지니아, 애리조나, 아이다호, 몬태나, 유타가 비슷한 소송을 냈다고 적었어요. 발표문마다 언급한 주의 범위가 달라서 이 카드는 소송 건수를 하나로 확정하지 않아요.\n\n## 설명된 내용은 모두 소송을 낸 쪽의 주장이에요\n\n각 법무장관실이 밝힌 내용은 OpenAI가 ChatGPT의 안전성에 관해 부모와 주민을 오도했다는 주 정부의 주장이며 법원이 판단한 사실이 아니에요. 이 카드는 각 주 공식 보도자료에 적힌 표현만 옮겼고 OpenAI의 입장은 다루지 않아요.",
