          "deck": "멤버 24명의 실시간 AI 아바타와 영상통화를 할 수 있어요",
          "summary": "이스트소프트와 블루밍그레이스가 K-POP 그룹 A2O LITE와 A2O SOUL 멤버 24명의 AI 아바타와 영상통화하는 앱 블루밍톡을 선보였어요. 아바타는 이스트소프트의 실시간 Perso Interactive 기술로 만들어졌고 아티스트의 촬영 데이터를 바탕으로 해요.",
          "content": "이스트소프트는 15일 블루밍그레이스와 함께 K-POP 아티스트 영상통화 앱 '블루밍톡(BloomingTalk)'을 선보인다고 밝혔어요. 앱은 이스트소프트의 실시간 대화형 AI 아바타 서비스 'Perso Interactive'를 바탕으로 해요.\n\n이 앱에서는 K-POP 그룹 A2O SOUL과 A2O LITE 멤버 24명 전원의 AI 아바타와 영상통화를 할 수 있어요. 이스트소프트는 아바타를 실제 아티스트의 촬영 데이터로 멤버마다 개별 제작해 각자의 외모와 분위기를 구현했고, 글로벌 팬과의 소통을 맡긴다고 설명했어요.\n\n역할은 나뉘어 있어요. 블루밍그레이스는 서비스를 운영하고 아티스트 IP를 관리하며, 이스트소프트는 아바타 제작과 실시간 렌더링·스트리밍을 맡았어요. 앱 개발은 Mindlogic이 했어요.\n\n출시 시점은 보도마다 달라요. 이스트소프트 게시글은 15일을 기준으로 하지만 텐아시아는 서비스가 14일부터 제공되고 있다고 전했어요. DM과 음성통화 기능은 AI타임스 기사에만 언급되고 이스트소프트 게시글에는 영상통화만 적혀 있어서, 확인된 기능은 영상통화예요.",
