          "content": "카카오는 10월 13일과 14일 카카오 AI 캠퍼스에서 열린 if(kakao)26에서 개인화 기반 에이전트 서비스와 기술을 선보였다고 밝혔어요. 보도자료는 2026년 10월 13일자예요.\n\n카나나 스페이스는 카카오톡 안에서 어디서든 불러 쓸 수 있는 AI 어시스턴트예요. 카카오는 13일부터 카나나 스페이스 웹사이트에서 사전 신청을 받고 있고, 12월부터 사전 신청자 가운데 일부를 선정해 비공개 베타 테스트(CBT)를 진행한다고 밝혔어요.\n\nKanvas는 PC에서 에이전트 팀을 만들고 실행하는 서비스예요. 카카오는 소규모 이용자를 대상으로 한 비공개 베타 테스트를 이르면 올해 안에 시작하고, 내년 상반기에는 카카오톡에서 에이전트 팀을 연결할 계획이라고 설명했어요.\n\n두 서비스 모두 정식 출시가 아니라 사전 신청과 비공개 베타를 앞둔 발표예요. 일반 이용자가 지금 바로 쓸 수 있는 서비스는 아니에요.",
